return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'ವೂಕಾಮರ್ಸ್','Go to Plugin Search' => 'ಪ್ಲಗಿನ್ ಹುಡುಕಾಟಕ್ಕೆ ಹೋಗಿ','Activate %s' => '%s ಸಕ್ರಿಯಗೊಳಿಸಿ','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s ಗೆ</strong> <strong>%2$s ಅನ್ನು</strong> ಸ್ಥಾಪಿಸಿ ಸಕ್ರಿಯಗೊಳಿಸುವ ಅಗತ್ಯವಿದೆ. <a href="%4$s">%3$s</a>','Enter your code here' => 'ನಿಮ್ಮ ಕೋಡ್ ಅನ್ನು ಇಲ್ಲಿ ನಮೂದಿಸಿ','Add %s' => '%s ಸೇರಿಸಿ','Remove' => 'ತೆಗೆದುಹಾಕಿ','Order number and receipt will be sent to this email address.' => 'ಆರ್ಡರ್ ಸಂಖ್ಯೆ ಮತ್ತು ರಶೀದಿಯನ್ನು ಈ ಇಮೇಲ್ ವಿಳಾಸಕ್ಕೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','Apartment, unit, building, floor, etc.' => 'ಅಪಾರ್ಟ್‌ಮೆಂಟ್, ಯೂನಿಟ್, ಕಟ್ಟಡ, ಮಹಡಿ, ಇತ್ಯಾದಿ.','Shipping phone' => 'ಶಿಪ್ಪಿಂಗ್ ಫೋನ್','Only used for shipping-related questions.' => 'ಶಿಪ್ಪಿಂಗ್ ಸಂಬಂಧಿತ ಪ್ರಶ್ನೆಗಳಿಗೆ ಮಾತ್ರ ಬಳಸಲಾಗುತ್ತದೆ.','Single step' => 'ಒಂದೇ ಹೆಜ್ಜೆ','Click to go to the order summary' => 'ಆರ್ಡರ್ ಸಾರಾಂಶಕ್ಕೆ ಹೋಗಲು ಕ್ಲಿಕ್ ಮಾಡಿ','Cart total:' => 'ಕಾರ್ಟ್ ಒಟ್ಟು:','Proceed to %s' => '%s ಗೆ ಮುಂದುವರಿಯಿರಿ','Proceed to contact' => 'ಸಂಪರ್ಕಕ್ಕೆ ಮುಂದುವರಿಯಿರಿ','Proceed to shipping' => 'ಸಾಗಣೆಗೆ ಮುಂದುವರಿಯಿರಿ','Proceed to billing' => 'ಬಿಲ್ಲಿಂಗ್‌ಗೆ ಮುಂದುವರಿಯಿರಿ','Proceed to payment' => 'ಪಾವತಿಗೆ ಮುಂದುವರಿಯಿರಿ','Shipping method' => 'ಸಾಗಣೆ ವಿಧಾನ','Additional notes' => 'ಹೆಚ್ಚುವರಿ ಟಿಪ್ಪಣಿಗಳು','Payment method' => 'ಪಾವತಿ ವಿಧಾನ','Step %1$s of %2$s' => '%2$s ರಲ್ಲಿ %1$s ಹಂತ','Change: %s' => 'ಬದಲಾವಣೆ: %s','Not selected yet.' => 'ಇನ್ನೂ ಆಯ್ಕೆಯಾಗಿಲ್ಲ.','Same as shipping address' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ','Same as billing address' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ','Order summary' => 'ಆರ್ಡರ್ ಸಾರಾಂಶ','Edit cart' => 'ಕಾರ್ಟ್ ಸಂಪಾದಿಸಿ','Did you mean %s?' => 'ನೀವು %s ಎಂದು ಹೇಳುತ್ತಿದ್ದೀರಾ?','Change email address to: {suggestion-value}' => 'ಇಮೇಲ್ ವಿಳಾಸವನ್ನು ಇದಕ್ಕೆ ಬದಲಾಯಿಸಿ: {suggestion-value}','This is a required field.' => 'ಇದು ಕಡ್ಡಾಯ ಕ್ಷೇತ್ರವಾಗಿದೆ.','This is not a valid email address.' => 'ಇದು ಮಾನ್ಯವಾದ ಇಮೇಲ್ ವಿಳಾಸವಲ್ಲ.','This field does not match the related field value.' => 'ಈ ಕ್ಷೇತ್ರವು ಸಂಬಂಧಿತ ಕ್ಷೇತ್ರ ಮೌಲ್ಯಕ್ಕೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; CPF ಸಂಖ್ಯೆ ಅಮಾನ್ಯವಾಗಿದೆ.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ ಸಂಖ್ಯೆ &quot;{cnpj_number}&quot; ಅಮಾನ್ಯವಾಗಿದೆ.','(Required)' => '(ಅಗತ್ಯವಿದೆ)','Checkout Header - Desktop' => 'ಚೆಕ್ಔಟ್ ಹೆಡರ್ - ಡೆಸ್ಕ್‌ಟಾಪ್','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'ದೊಡ್ಡ ಪರದೆಗಳಿಗೆ ಚೆಕ್ಔಟ್ ಹೆಡರ್‌ನಲ್ಲಿ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ. ಪ್ಲಗಿನ್‌ನ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಬಳಸುತ್ತಿದ್ದರೆ ಮಾತ್ರ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Checkout Header - Mobile' => 'ಚೆಕ್ಔಟ್ ಹೆಡರ್ - ಮೊಬೈಲ್','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'ಮೊಬೈಲ್ ಸಾಧನಗಳಿಗೆ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಕೆಳಗೆ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ. ಪ್ಲಗಿನ್‌ನ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಬಳಸುತ್ತಿದ್ದರೆ ಮಾತ್ರ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Checkout Sidebar' => 'ಚೆಕ್ಔಟ್ ಸೈಡ್‌ಬಾರ್','Display widgets on the checkout sidebar after the order summary.' => 'ಆರ್ಡರ್ ಸಾರಾಂಶದ ನಂತರ ಚೆಕ್ಔಟ್ ಸೈಡ್‌ಬಾರ್‌ನಲ್ಲಿ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Checkout Order Summary' => 'ಚೆಕ್ಔಟ್ ಆರ್ಡರ್ ಸಾರಾಂಶ','Display widgets inside the order summary at the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಆರ್ಡರ್ ಸಾರಾಂಶದ ಒಳಗೆ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Checkout Below Place Order' => 'ಪ್ಲೇಸ್ ಆರ್ಡರ್ ಕೆಳಗೆ ಚೆಕ್ಔಟ್ ಮಾಡಿ','Display widgets below the place order button at the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಪ್ಲೇಸ್ ಆರ್ಡರ್ ಬಟನ್ ಕೆಳಗೆ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Checkout Footer' => 'ಚೆಕ್ಔಟ್ ಅಡಿಟಿಪ್ಪಣಿ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ಚೆಕ್ಔಟ್ ಅಡಿಟಿಪ್ಪಣಿಯಲ್ಲಿ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ. ಪ್ಲಗಿನ್‌ನ ಚೆಕ್ಔಟ್ ಅಡಿಟಿಪ್ಪಣಿ ಬಳಸುತ್ತಿದ್ದರೆ ಮಾತ್ರ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Classic' => 'ಕ್ಲಾಸಿಕ್','Boxed' => 'ಪೆಟ್ಟಿಗೆ','Split' => 'ವಿಭಜನೆ','Minimalist' => 'ಕನಿಷ್ಠೀಯತಾವಾದಿ','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'ಕೋಡ್‌ರಾಕ್ಜ್‌ನಿಂದ ದ್ರವ ಚೆಕ್‌ಔಟ್ ಮತ್ತು ವಿತರಣಾ ದಿನಾಂಕ ಪ್ಲಗಿನ್‌ಗಳು','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>ನೀವು CodeRockz ನಿಂದ WooCommerce ಗಾಗಿ ಡೆಲಿವರಿ &amp; ಪಿಕಪ್ ದಿನಾಂಕ ಸಮಯ (ಉಚಿತ ಮತ್ತು PRO) ಪ್ಲಗಿನ್‌ಗಳನ್ನು ಬಳಸುತ್ತಿರುವುದನ್ನು ನಾವು ಪತ್ತೆಹಚ್ಚಿದ್ದೇವೆ. ಈ ಪ್ಲಗಿನ್‌ಗಳೊಂದಿಗಿನ ಏಕೀಕರಣವನ್ನು Fluid Checkout PRO ಗೆ ಸರಿಸಲಾಗಿದೆ.</p>','Upgrade to PRO' => 'PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ','Fluid Checkout database updated successfully' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಡೇಟಾಬೇಸ್ ಅನ್ನು ಯಶಸ್ವಿಯಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ.','The database changes where applied successfully.' => 'ಯಶಸ್ವಿಯಾಗಿ ಅನ್ವಯಿಸಿದ ಸ್ಥಳದಲ್ಲಿ ಡೇಟಾಬೇಸ್ ಬದಲಾಗುತ್ತದೆ.','Dismiss' => 'ವಜಾಗೊಳಿಸಿ','Fluid Checkout database update' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಡೇಟಾಬೇಸ್ ನವೀಕರಣ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಕೆಲವು ಬದಲಾವಣೆಗಳು ಅಗತ್ಯವಿದೆ. ಯಾವುದೇ ನವೀಕರಣದಂತೆ, <strong>ಮುಂದುವರಿಯುವ ಮೊದಲು ನಿಮ್ಮ ವೆಬ್‌ಸೈಟ್‌ನ ಪೂರ್ಣ ಬ್ಯಾಕಪ್ ತೆಗೆದುಕೊಳ್ಳಲು</strong> ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.','Update database' => 'ಡೇಟಾಬೇಸ್ ನವೀಕರಿಸಿ','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ದ್ರವ ಚೆಕ್ಔಟ್ ಡಿವಿ ಬಿಲ್ಡರ್ ಚೆಕ್ಔಟ್ ವಿನ್ಯಾಸದೊಂದಿಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ಗೆ ಕೆಲಸ ಮಾಡಲು ಕ್ಲಾಸಿಕ್ WooCommerce ಶಾರ್ಟ್‌ಕೋಡ್ ಆಧಾರಿತ ಚೆಕ್‌ಔಟ್ ಫಾರ್ಮ್ ಅಗತ್ಯವಿದೆ. ಚೆಕ್‌ಔಟ್ ಪುಟದ ನೋಟ ಮತ್ತು ಭಾವನೆಯನ್ನು ಕಸ್ಟಮೈಸ್ ಮಾಡಲು ಡಿವಿ ಬಿಲ್ಡರ್ ಬಳಸುವಾಗ, ಕ್ಲಾಸಿಕ್ ಶಾರ್ಟ್‌ಕೋಡ್‌ಗಳನ್ನು ಚೆಕ್‌ಔಟ್ ಪುಟದ ಪ್ರತಿಯೊಂದು ಭಾಗಕ್ಕೂ ಡಿವಿ ಬಿಲ್ಡರ್‌ನಿಂದ ಕಸ್ಟಮ್ ವಿಜೆಟ್‌ಗಳೊಂದಿಗೆ ಬದಲಾಯಿಸಲಾಗುತ್ತದೆ. ಈ ಕಸ್ಟಮ್ ವಿಜೆಟ್‌ಗಳು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.</p><p> ದಯವಿಟ್ಟು ನಿಮ್ಮ ಚೆಕ್ಔಟ್ ಪುಟವನ್ನು ಡಿವಿ ಬಿಲ್ಡರ್ ವಿಜೆಟ್‌ಗಳ ಬದಲಿಗೆ <code>[woocommerce_checkout]</code> ಎಂಬ ಶಾರ್ಟ್‌ಕೋಡ್ ಹೊಂದಿರುವ ಪಠ್ಯ ವಿಜೆಟ್‌ನೊಂದಿಗೆ ಸಂಪಾದಿಸಿ.</p>','Edit the checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟವನ್ನು ಸಂಪಾದಿಸಿ','Read the documentation.' => 'ದಸ್ತಾವೇಜನ್ನು ಓದಿ.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಬಳಸುವಾಗ ಜರ್ಮನೀಕರಿಸಿದ PRO ಮಲ್ಟಿಸ್ಟೆಪ್ ಚೆಕ್ಔಟ್ ವೈಶಿಷ್ಟ್ಯವನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬೇಕಾಗುತ್ತದೆ.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಬಳಸುವಾಗ, ಜರ್ಮನೀಕರಿಸಿದ PRO ಪ್ಲಗಿನ್‌ನಿಂದ ಬಹುಹಂತದ ವೈಶಿಷ್ಟ್ಯವು ಅನಗತ್ಯವಾಗುತ್ತದೆ ಮತ್ತು <strong>ಹೊಸ ಆರ್ಡರ್‌ಗಳನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುವಾಗ ನಿರ್ಣಾಯಕ ದೋಷಗಳನ್ನು</strong> ಉಂಟುಮಾಡಬಹುದು. ದಯವಿಟ್ಟು ಪ್ಲಗಿನ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಜರ್ಮನೀಕರಿಸಿದ PRO ಬಹುಹಂತದ ಚೆಕ್‌ಔಟ್ ವೈಶಿಷ್ಟ್ಯವನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ.','Go to Germanized settings' => 'ಜರ್ಮನೀಕರಿಸಿದ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಹೋಗಿ','Thanks for choosing Fluid Checkout!' => 'ದ್ರವ ಚೆಕ್ಔಟ್ ಆಯ್ಕೆ ಮಾಡಿದ್ದಕ್ಕಾಗಿ ಧನ್ಯವಾದಗಳು!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'ನೀವು ಸ್ವಲ್ಪ ಸಮಯದಿಂದ ಪ್ಲಗಿನ್ ಬಳಸುತ್ತಿದ್ದೀರಿ. ಇಲ್ಲಿಯವರೆಗೆ ನಿಮಗೆ ಅದು ಹೇಗೆ ಇಷ್ಟವಾಯಿತು?<br> ದಯವಿಟ್ಟು ನಮಗೆ ತ್ವರಿತ ರೇಟಿಂಗ್ ನೀಡಿ, ನಾವು ಪ್ರತಿ ಪ್ರತಿಕ್ರಿಯೆಗೂ ಕೃತಜ್ಞರಾಗಿರುತ್ತೇವೆ ಮತ್ತು ಅದು ಪ್ಲಗಿನ್ ಅನ್ನು ಸುಧಾರಿಸುವುದನ್ನು ಮುಂದುವರಿಸಲು ನಮ್ಮನ್ನು ಪ್ರೋತ್ಸಾಹಿಸುತ್ತದೆ :)','Rate the plugin' => 'ಪ್ಲಗಿನ್ ಅನ್ನು ರೇಟ್ ಮಾಡಿ','I need help!' => 'ನನಗೆ ಸಹಾಯ ಬೇಕು!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ಕ್ವಾಡ್‌ಲೇಯರ್‌ಗಳ WooCommerce Checkout ಮ್ಯಾನೇಜರ್‌ನ ಕೆಲವು ವೈಶಿಷ್ಟ್ಯಗಳು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನೊಂದಿಗೆ ಬಳಸುವಾಗ ನಿರೀಕ್ಷೆಯಂತೆ ಕಾರ್ಯನಿರ್ವಹಿಸದಿರಬಹುದು. ಹೆಚ್ಚಿನ ಮಾಹಿತಿ ಮತ್ತು ಪರ್ಯಾಯ ಪರಿಹಾರಗಳಿಗಾಗಿ <a href="%s">ನಮ್ಮ ದಸ್ತಾವೇಜನ್ನು</a> ಓದಿ.','Read documentation' => 'ದಸ್ತಾವೇಜನ್ನು ಓದಿ','Don\'t show this again' => 'ಇದನ್ನು ಮತ್ತೆ ತೋರಿಸಬೇಡಿ','Fluid Checkout PRO' => 'ದ್ರವ ಚೆಕ್ಔಟ್ ಪ್ರೊ','More design templates' => 'ಇನ್ನಷ್ಟು ವಿನ್ಯಾಸ ಟೆಂಪ್ಲೇಟ್‌ಗಳು','Optimized cart page' => 'ಅತ್ಯುತ್ತಮಗೊಳಿಸಿದ ಕಾರ್ಟ್ ಪುಟ','Optimized order received / thank you page' => 'ಅತ್ಯುತ್ತಮಗೊಳಿಸಿದ ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಲಾಗಿದೆ / ಧನ್ಯವಾದ ಪುಟ','Edit cart contents at checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಕಾರ್ಟ್ ವಿಷಯಗಳನ್ನು ಸಂಪಾದಿಸಿ','Account matching / user matching' => 'ಖಾತೆ ಹೊಂದಾಣಿಕೆ / ಬಳಕೆದಾರ ಹೊಂದಾಣಿಕೆ','Trust symbols on the cart and thank you pages' => 'ಕಾರ್ಟ್ ಮತ್ತು ಧನ್ಯವಾದ ಪುಟಗಳಲ್ಲಿರುವ ಚಿಹ್ನೆಗಳನ್ನು ನಂಬಿರಿ.','More positions for the coupon code on the checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್‌ಗಾಗಿ ಹೆಚ್ಚಿನ ಸ್ಥಾನಗಳು','International phone numbers' => 'ಅಂತರರಾಷ್ಟ್ರೀಯ ಫೋನ್ ಸಂಖ್ಯೆಗಳು','Gift messages and packing slips' => 'ಉಡುಗೊರೆ ಸಂದೇಶಗಳು ಮತ್ತು ಪ್ಯಾಕಿಂಗ್ ಸ್ಲಿಪ್‌ಗಳು','Local pickup and in-store collection' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್ ಮತ್ತು ಅಂಗಡಿಯಲ್ಲಿನ ಸಂಗ್ರಹಣೆ','EU-VAT Assistant' => 'EU-VAT ಸಹಾಯಕ','I already have it – Hide this offer' => 'ನನ್ನ ಬಳಿ ಈಗಾಗಲೇ ಇದೆ - ಈ ಆಫರ್ ಅನ್ನು ಮರೆಮಾಡಿ','Activated' => 'ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ','Address book' => 'ವಿಳಾಸ ಪುಸ್ತಕ','Select an image' => 'ಚಿತ್ರವನ್ನು ಆಯ್ಕೆಮಾಡಿ','Cart layout' => 'ಕಾರ್ಟ್ ವಿನ್ಯಾಸ','Cart optimizations' => 'ಕಾರ್ಟ್ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳು','Enable cart page optimizations' => 'ಕಾರ್ಟ್ ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Header and footer template' => 'ಹೆಡರ್ ಮತ್ತು ಫೂಟರ್ ಟೆಂಪ್ಲೇಟ್','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ಅಡ್ಡಿಪಡಿಸುವಿಕೆ ಮುಕ್ತ ಪುಟದ ಶಿರೋಲೇಖ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿಯನ್ನು ಬಳಸಬೇಕೆ ಅಥವಾ ಪ್ರಸ್ತುತ ಸಕ್ರಿಯವಾಗಿರುವ ಥೀಮ್‌ನ ಶಿರೋಲೇಖ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳಬೇಕೆ ಎಂಬುದನ್ನು ನಿಯಂತ್ರಿಸುತ್ತದೆ.','Distraction free header and footer' => 'ಗೊಂದಲ ಮುಕ್ತ ಹೆಡರ್ ಮತ್ತು ಫೂಟರ್','Theme\'s header and footer' => 'ಥೀಮ್‌ನ ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿ','Cart elements' => 'ಕಾರ್ಟ್ ಅಂಶಗಳು','Make the order summary stay visible on the cart page while scrolling' => 'ಸ್ಕ್ರೋಲ್ ಮಾಡುವಾಗ ಆರ್ಡರ್ ಸಾರಾಂಶವು ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಗೋಚರಿಸುವಂತೆ ಮಾಡಿ.','Coupon codes' => 'ಕೂಪನ್ ಕೋಡ್‌ಗಳು','Hidden' => 'ಮರೆಮಾಡಲಾಗಿದೆ','Before the cart items section' => 'ಕಾರ್ಟ್ ಐಟಂಗಳ ವಿಭಾಗದ ಮೊದಲು','Inside the cart items section' => 'ಕಾರ್ಟ್ ಐಟಂಗಳ ವಿಭಾಗದ ಒಳಗೆ','After the cart items section' => 'ಕಾರ್ಟ್ ಐಟಂಗಳ ವಿಭಾಗದ ನಂತರ','Before the shipping section' => 'ಸಾಗಣೆ ವಿಭಾಗದ ಮೊದಲು','After the shipping section' => 'ಸಾಗಣೆ ವಿಭಾಗದ ನಂತರ','Before the order summary' => 'ಆದೇಶದ ಮೊದಲು ಸಾರಾಂಶ','Inside the order summary' => 'ಆರ್ಡರ್ ಸಾರಾಂಶದ ಒಳಗೆ','Before the order totals' => 'ಆದೇಶದ ಮೊತ್ತ ಮುಗಿಯುವ ಮೊದಲು','After the order totals' => 'ಆರ್ಡರ್ ಮೊತ್ತದ ನಂತರ','After the order summary' => 'ಆದೇಶದ ಸಾರಾಂಶದ ನಂತರ','Shipping' => 'ಶಿಪ್ಪಿಂಗ್','Select position where to display the shipping costs and calculator on the cart page.' => 'ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಶಿಪ್ಪಿಂಗ್ ವೆಚ್ಚಗಳು ಮತ್ತು ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಅನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕಾದ ಸ್ಥಾನವನ್ನು ಆಯ್ಕೆಮಾಡಿ.','Display as a cart section' => 'ಕಾರ್ಟ್ ವಿಭಾಗವಾಗಿ ಪ್ರದರ್ಶಿಸಿ','Cross-sells' => 'ಕ್ರಾಸ್-ಸೆಲ್ಸ್','Select position where to display the cross-sells section on the cart page.' => 'ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಕ್ರಾಸ್-ಸೆಲ್ಸ್ ವಿಭಾಗವನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕಾದ ಸ್ಥಾನವನ್ನು ಆಯ್ಕೆಮಾಡಿ.','Before the cart actions' => 'ಕಾರ್ಟ್ ಕ್ರಮಗಳ ಮೊದಲು','After the cart actions' => 'ಕಾರ್ಟ್ ಕ್ರಿಯೆಗಳ ನಂತರ','Layout of cross-sell items on the cart page.' => 'ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಅಡ್ಡ-ಮಾರಾಟದ ವಸ್ತುಗಳ ವಿನ್ಯಾಸ.','Optimized horizontal cross-sells layout' => 'ಆಪ್ಟಿಮೈಸ್ಡ್ ಸಮತಲ ಕ್ರಾಸ್-ಸೆಲ್ಸ್ ವಿನ್ಯಾಸ','Theme\'s cross-sells layout' => 'ಥೀಮ್‌ನ ಕ್ರಾಸ್-ಸೆಲ್ಲ್ಸ್ ವಿನ್ಯಾಸ','Number of cross-sell items to display on the cart page' => 'ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಲು ಅಡ್ಡ-ಮಾರಾಟದ ಐಟಂಗಳ ಸಂಖ್ಯೆ','Add widget areas to the cart page' => 'ಕಾರ್ಟ್ ಪುಟಕ್ಕೆ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಸೇರಿಸಿ','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'ಈ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಟ್ರಸ್ಟ್ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.','Checkout' => 'ಚೆಕ್ಔಟ್','Checkout layout' => 'ಚೆಕ್ಔಟ್ ವಿನ್ಯಾಸ','Design template' => 'ವಿನ್ಯಾಸ ಟೆಂಪ್ಲೇಟ್','Dark mode' => 'ಕತ್ತಲೆ ಮೋಡ್','Enable dark mode' => 'ಡಾರ್ಕ್ ಮೋಡ್ ಸಕ್ರಿಯಗೊಳಿಸಿ','Logo image' => 'ಲೋಗೋ ಚಿತ್ರ','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ಚೆಕ್ಔಟ್ ಪುಟದ ಹೆಡರ್‌ನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಲು ಚಿತ್ರವನ್ನು ಆರಿಸಿ. ಅಡ್ಡಿಪಡಿಸುವಿಕೆ ಮುಕ್ತ ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','Header background color' => 'ಶಿರೋಲೇಖ ಹಿನ್ನೆಲೆ ಬಣ್ಣ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ಚೆಕ್ಔಟ್ ಪುಟದ ಹೆಡರ್‌ಗೆ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಆರಿಸಿ. ಅಡ್ಡಿಪಡಿಸುವಿಕೆ ಮುಕ್ತ ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','HTML color value. ie: #f3f3f3' => 'HTML ಬಣ್ಣದ ಮೌಲ್ಯ. ಅಂದರೆ: #f3f3f3','Page background color' => 'ಪುಟದ ಹಿನ್ನೆಲೆ ಬಣ್ಣ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ಚೆಕ್ಔಟ್ ಪುಟಕ್ಕೆ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಆರಿಸಿ. <em>ಮುಖ್ಯ</em> ಭಾಗಕ್ಕೆ ಬಣ್ಣವನ್ನು ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ.','Footer background color' => 'ಅಡಿಟಿಪ್ಪಣಿ ಹಿನ್ನೆಲೆ ಬಣ್ಣ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ಚೆಕ್ಔಟ್ ಪುಟದ ಅಡಿಟಿಪ್ಪಣಿಗೆ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಆರಿಸಿ. ಅಡ್ಡಿಪಡಿಸುವಿಕೆ ಮುಕ್ತ ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','Progress bar' => 'ಪ್ರಗತಿ ಪಟ್ಟಿ','Display the checkout progress bar when using multi-step checkout layout' => 'ಬಹು-ಹಂತದ ಚೆಕ್‌ಔಟ್ ವಿನ್ಯಾಸವನ್ನು ಬಳಸುವಾಗ ಚೆಕ್‌ಔಟ್ ಪ್ರಗತಿ ಪಟ್ಟಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ','Make the checkout progress bar stay visible while scrolling' => 'ಸ್ಕ್ರೋಲ್ ಮಾಡುವಾಗ ಚೆಕ್ಔಟ್ ಪ್ರಗತಿ ಪಟ್ಟಿ ಗೋಚರಿಸುವಂತೆ ಮಾಡಿ','Express checkout' => 'ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್ಔಟ್','Enable the express checkout section' => 'ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್‌ಔಟ್ ವಿಭಾಗವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'ಬೆಂಬಲಿತ ಪಾವತಿ ಗೇಟ್‌ವೇಗಳು ಈ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್‌ಔಟ್ ವಿಭಾಗವನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ.','Display express checkout buttons in one line for larger screens' => 'ದೊಡ್ಡ ಪರದೆಗಳಿಗೆ ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್‌ಔಟ್ ಬಟನ್‌ಗಳನ್ನು ಒಂದೇ ಸಾಲಿನಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ.','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'ಹೊಂದಾಣಿಕೆಯ ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್‌ಔಟ್ ಪಾವತಿ ಗೇಟ್‌ವೇ ಮೂಲಕ ಪಾವತಿಸುವಾಗ ಹೆಚ್ಚುವರಿ ಚೆಕ್‌ಔಟ್ ಅಗತ್ಯವಿರುವ ಕ್ಷೇತ್ರಗಳನ್ನು ನಿರ್ಲಕ್ಷಿಸಿ.','Make the order summary stay visible while scrolling' => 'ಸ್ಕ್ರೋಲ್ ಮಾಡುವಾಗ ಆರ್ಡರ್ ಸಾರಾಂಶವು ಗೋಚರಿಸುವಂತೆ ಮಾಡಿ','Choose a background color for the order summary section.' => 'ಆರ್ಡರ್ ಸಾರಾಂಶ ವಿಭಾಗಕ್ಕೆ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಆರಿಸಿ.','Highlight the order totals row in the order summary table' => 'ಆರ್ಡರ್ ಸಾರಾಂಶ ಕೋಷ್ಟಕದಲ್ಲಿ ಆರ್ಡರ್ ಮೊತ್ತಗಳ ಸಾಲನ್ನು ಹೈಲೈಟ್ ಮಾಡಿ','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ಆರ್ಡರ್ ಸಾರಾಂಶ ವಿಭಾಗವು ಹೈಲೈಟ್ ಮಾಡಿದ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಹೊಂದಿಲ್ಲದಿದ್ದಾಗ ಹೆಚ್ಚು ಉಪಯುಕ್ತವಾಗಿದೆ. ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ PRO ಬಳಸುವಾಗ ಕಾರ್ಟ್, ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಮತ್ತು ವೀಕ್ಷಣೆ ಆರ್ಡರ್ ಪುಟಗಳಿಗೂ ಅನ್ವಯಿಸಬಹುದು.','Action link on the order summary at checkout.' => 'ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ಆರ್ಡರ್ ಸಾರಾಂಶದ ಮೇಲಿನ ಕ್ರಿಯೆಯ ಲಿಂಕ್.','Edit cart link' => 'ಕಾರ್ಟ್ ಲಿಂಕ್ ಸಂಪಾದಿಸಿ','Cart items count' => 'ಕಾರ್ಟ್ ಐಟಂಗಳ ಎಣಿಕೆ','Link to shop page' => 'ಅಂಗಡಿ ಪುಟಕ್ಕೆ ಲಿಂಕ್ ಮಾಡಿ','Cart items' => 'ಕಾರ್ಟ್ ಐಟಂಗಳು','Hide cart items errors at the checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಕಾರ್ಟ್ ಐಟಂಗಳ ದೋಷಗಳನ್ನು ಮರೆಮಾಡಿ.','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ಚೆಕ್ಔಟ್ ಪುಟದ ಮೇಲ್ಭಾಗದಲ್ಲಿ ಕಾರ್ಟ್ ಐಟಂಗಳ ದೋಷ ಸಂದೇಶವನ್ನು ಪ್ರದರ್ಶಿಸಬೇಡಿ. ಖರೀದಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್ ಅನ್ನು ಸಲ್ಲಿಸುವಾಗ, ಈ ದೋಷ ಸಂದೇಶಗಳನ್ನು ಯಾವಾಗಲೂ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Place order' => 'ಆರ್ಡರ್ ಮಾಡಿ','Define the position to display "Place order" and terms checkbox section.' => '&quot;ಆದೇಶವನ್ನು ಇರಿಸಿ&quot; ಮತ್ತು ಪದಗಳ ಚೆಕ್‌ಬಾಕ್ಸ್ ವಿಭಾಗವನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕಾದ ಸ್ಥಾನವನ್ನು ವಿವರಿಸಿ.','Some options might not be compatible with some plugins and themes.' => 'ಕೆಲವು ಆಯ್ಕೆಗಳು ಕೆಲವು ಪ್ಲಗಿನ್‌ಗಳು ಮತ್ತು ಥೀಮ್‌ಗಳೊಂದಿಗೆ ಹೊಂದಿಕೆಯಾಗದಿರಬಹುದು.','Below the payment section' => 'ಪಾವತಿ ವಿಭಾಗದ ಕೆಳಗೆ','Below the order summary' => 'ಆದೇಶದ ಸಾರಾಂಶದ ಕೆಳಗೆ','Both below the payment section and the order summary' => 'ಪಾವತಿ ವಿಭಾಗ ಮತ್ತು ಆರ್ಡರ್ ಸಾರಾಂಶದ ಕೆಳಗೆ ಎರಡೂ','Add widget areas to the checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟಕ್ಕೆ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಸೇರಿಸಿ','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ಈ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಟ್ರಸ್ಟ್ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.','Display the coupon codes section title' => 'ಕೂಪನ್ ಕೋಡ್‌ಗಳ ವಿಭಾಗದ ಶೀರ್ಷಿಕೆಯನ್ನು ಪ್ರದರ್ಶಿಸಿ','Select position where to display the coupon codes section on the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್‌ಗಳ ವಿಭಾಗವನ್ನು ಎಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆಯ್ಕೆಮಾಡಿ.','Before the checkout steps' => 'ಚೆಕ್ಔಟ್ ಹಂತಗಳ ಮೊದಲು','As a substep before payment methods' => 'ಪಾವತಿ ವಿಧಾನಗಳ ಮೊದಲು ಉಪಹಂತವಾಗಿ','As a substep after payment methods' => 'ಪಾವತಿ ವಿಧಾನಗಳ ನಂತರದ ಉಪ ಹಂತವಾಗಿ','Default button style' => 'ಡೀಫಾಲ್ಟ್ ಬಟನ್ ಶೈಲಿ','"Add" link button' => '&quot;ಲಿಂಕ್ ಸೇರಿಸು&quot; ಬಟನ್','Checkout fields' => 'ಚೆಕ್ಔಟ್ ಕ್ಷೇತ್ರಗಳು','Optional fields' => 'ಐಚ್ಛಿಕ ಕ್ಷೇತ್ರಗಳು','Hide optional fields behind a link button' => 'ಲಿಂಕ್ ಬಟನ್‌ನ ಹಿಂದೆ ಐಚ್ಛಿಕ ಕ್ಷೇತ್ರಗಳನ್ನು ಮರೆಮಾಡಿ','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'ತೆರೆದ ಇನ್‌ಪುಟ್ ಕ್ಷೇತ್ರಗಳ ಸಂಖ್ಯೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಈ ಆಯ್ಕೆಯನ್ನು ಪರಿಶೀಲಿಸಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ಸಂಶೋಧನೆಯನ್ನು ಓದಿ</a> .','Do not hide "Address line 2" fields behind a link button' => 'ಲಿಂಕ್ ಬಟನ್ ಹಿಂದೆ &quot;ವಿಳಾಸ ಸಾಲು 2&quot; ಕ್ಷೇತ್ರಗಳನ್ನು ಮರೆಮಾಡಬೇಡಿ.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'ಹೆಚ್ಚಿನ ಗ್ರಾಹಕರಿಗೆ &quot;ವಿಳಾಸ ಸಾಲು 2&quot; ಕ್ಷೇತ್ರವು ನಿಜವಾಗಿಯೂ ಅಗತ್ಯವಿದ್ದಾಗ ಅಥವಾ ಸರಿಯಾದ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವನ್ನು ಪಡೆಯುವುದು ನಿರ್ಣಾಯಕವಾಗಿದ್ದಾಗ (ಅಂದರೆ ಆಹಾರ ಮತ್ತು ಇತರ ಹಾಳಾಗುವ ಉತ್ಪನ್ನಗಳನ್ನು ತಲುಪಿಸುತ್ತಿದ್ದರೆ) ಮಾತ್ರ ಶಿಫಾರಸು ಮಾಡಲಾಗುತ್ತದೆ.','Billing address' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ','Select position where to display the billing address section on the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ಎಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕು ಎಂಬುದನ್ನು ಆಯ್ಕೆಮಾಡಿ.','As a step before shipping' => 'ಸಾಗಣೆಗೆ ಒಂದು ಹೆಜ್ಜೆ ಮೊದಲು','As a sub-step before the shipping address section' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗದ ಮೊದಲು ಉಪ-ಹಂತವಾಗಿ','As a sub-step after the shipping address section' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗದ ನಂತರ ಉಪ-ಹಂತವಾಗಿ','As a step after shipping' => 'ಸಾಗಣೆಯ ನಂತರದ ಒಂದು ಹಂತವಾಗಿ','As a sub-step before the payment section' => 'ಪಾವತಿ ವಿಭಾಗದ ಮೊದಲು ಉಪ-ಹಂತವಾಗಿ','Force billing and shipping addresses to the same (single section)' => 'ಬಿಲ್ಲಿಂಗ್ ಮತ್ತು ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸಗಳನ್ನು ಒಂದೇ (ಒಂದೇ ವಿಭಾಗ) ಗೆ ಒತ್ತಾಯಿಸಿ','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;ಶಿಪ್ಪಿಂಗ್/ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ&quot; ಎಂಬ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಪರಿಶೀಲಿಸಲಾಗಿದೆ.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ಮೊದಲು ಪ್ರದರ್ಶಿಸಿದಾಗ &quot;ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ&quot; ಎಂಬ ಚೆಕ್‌ಬಾಕ್ಸ್ ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಪರಿಶೀಲಿಸಿದಂತೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.<br> ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ಮೊದಲು ಪ್ರದರ್ಶಿಸಿದಾಗ &quot;ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ&quot; ಚೆಕ್‌ಬಾಕ್ಸ್ ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಗುರುತಿಸಿದಂತೆ ಪ್ರಾರಂಭವಾಗುತ್ತದೆ.<br> ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ತೆರೆದ ಇನ್‌ಪುಟ್ ಕ್ಷೇತ್ರಗಳ ಸಂಖ್ಯೆಯನ್ನು ಗಣನೀಯವಾಗಿ ಕಡಿಮೆ ಮಾಡಲು ಈ ಆಯ್ಕೆಯನ್ನು ಪರಿಶೀಲಿಸಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ಸಂಶೋಧನೆಯನ್ನು ಓದಿ</a> .','Highlight the billing address section in the checkout form' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ಹೈಲೈಟ್ ಮಾಡಿ','Shipping address' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ','Highlight the shipping address section in the checkout form' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ಹೈಲೈಟ್ ಮಾಡಿ.','Shipping methods' => 'ಸಾಗಣೆ ವಿಧಾನಗಳು','Choose in which position to display the shipping methods section.' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಧಾನಗಳ ವಿಭಾಗವನ್ನು ಯಾವ ಸ್ಥಾನದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Before shipping address' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸಕ್ಕೂ ಮುನ್ನ','After shipping address' => 'ಶಿಪ್ಪಿಂಗ್ ನಂತರದ ವಿಳಾಸ','Local pickup' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್','Removes shipping address section when a local pickup shipping method is selected.' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್ ಶಿಪ್ಪಿಂಗ್ ವಿಧಾನವನ್ನು ಆಯ್ಕೆ ಮಾಡಿದಾಗ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವನ್ನು ತೆಗೆದುಹಾಕುತ್ತದೆ.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್ ಶಿಪ್ಪಿಂಗ್ ವಿಧಾನವನ್ನು ಆಯ್ಕೆ ಮಾಡಿದಾಗ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವನ್ನು ಪಿಕಪ್ ಪಾಯಿಂಟ್ ಸ್ಥಳದೊಂದಿಗೆ ಬದಲಾಯಿಸುತ್ತದೆ.','Choose which address to save as the shipping address for local pickup orders.' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್ ಆರ್ಡರ್‌ಗಳಿಗಾಗಿ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವಾಗಿ ಯಾವ ವಿಳಾಸವನ್ನು ಉಳಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Save the selected pickup location' => 'ಆಯ್ಕೆಮಾಡಿದ ಪಿಕಪ್ ಸ್ಥಳವನ್ನು ಉಳಿಸಿ','Save same as the billing address' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ ಉಳಿಸಿ','Do not save any shipping address' => 'ಯಾವುದೇ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವನ್ನು ಉಳಿಸಬೇಡಿ.','Company name field for shipping address' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸಕ್ಕಾಗಿ ಕಂಪನಿ ಹೆಸರಿನ ಕ್ಷೇತ್ರ','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗಕ್ಕಾಗಿ ಕಂಪನಿಯ ಹೆಸರಿನ ಕ್ಷೇತ್ರಕ್ಕೆ ಗೋಚರತೆಯನ್ನು ಬದಲಾಯಿಸಿ.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ಕ್ಷೇತ್ರವನ್ನು &quot;ಐಚ್ಛಿಕ&quot; ಎಂದು ಹೊಂದಿಸಿದ್ದರೆ, ಅದು ಪೂರ್ವನಿಯೋಜಿತ ಗೋಚರತೆಯ ಸ್ಥಿತಿಯಾಗಿದ್ದರೆ, ಇತರ ಪ್ಲಗಿನ್‌ಗಳು ತಮಗೆ ಅಗತ್ಯವಿರುವ ಯಾವುದೇ ಬದಲಾವಣೆಗಳನ್ನು ಅನ್ವಯಿಸಲು ಯಾವುದೇ ಬದಲಾವಣೆಗಳನ್ನು ಅನ್ವಯಿಸಲಾಗುವುದಿಲ್ಲ.','Hidden (remove field)' => 'ಮರೆಮಾಡಲಾಗಿದೆ (ಕ್ಷೇತ್ರವನ್ನು ತೆಗೆದುಹಾಕಿ)','Optional' => 'ಐಚ್ಛಿಕ','Required' => 'ಅಗತ್ಯವಿದೆ','Add shipping phone field to the checkout form.' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ಗೆ ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು ಸೇರಿಸಿ.','Choose in which step to display the shipping phone field.' => 'ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು ಯಾವ ಹಂತದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Contact step' => 'ಸಂಪರ್ಕ ಹಂತ','Billing phone' => 'ಬಿಲ್ಲಿಂಗ್ ಫೋನ್','Add billing phone field to the checkout form.' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ಗೆ ಬಿಲ್ಲಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು ಸೇರಿಸಿ.','Choose in which step to display the billing phone field.' => 'ಬಿಲ್ಲಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು ಯಾವ ಹಂತದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Show country code beside the flag' => 'ಧ್ವಜದ ಪಕ್ಕದಲ್ಲಿ ದೇಶದ ಕೋಡ್ ತೋರಿಸಿ','Show an example of a valid phone number inside phone fields' => 'ಫೋನ್ ಫೀಲ್ಡ್‌ಗಳ ಒಳಗೆ ಮಾನ್ಯವಾದ ಫೋನ್ ಸಂಖ್ಯೆಯ ಉದಾಹರಣೆಯನ್ನು ತೋರಿಸಿ.','Do not change placeholders' => 'ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳನ್ನು ಬದಲಾಯಿಸಬೇಡಿ','Show if not defined' => 'ವ್ಯಾಖ್ಯಾನಿಸದಿದ್ದರೆ ತೋರಿಸಿ','Always show' => 'ಯಾವಾಗಲೂ ತೋರಿಸು','Order notes' => 'ಆರ್ಡರ್ ಟಿಪ್ಪಣಿಗಳು','Define the visibility of the additional order notes field.' => 'ಹೆಚ್ಚುವರಿ ಆರ್ಡರ್ ಟಿಪ್ಪಣಿಗಳ ಕ್ಷೇತ್ರದ ಗೋಚರತೆಯನ್ನು ವಿವರಿಸಿ.','Gift options' => 'ಉಡುಗೊರೆ ಆಯ್ಕೆಗಳು','Allow customers to add a gift message and other gift related options to the order.' => 'ಗ್ರಾಹಕರು ಆರ್ಡರ್‌ಗೆ ಉಡುಗೊರೆ ಸಂದೇಶ ಮತ್ತು ಇತರ ಉಡುಗೊರೆ ಸಂಬಂಧಿತ ಆಯ್ಕೆಗಳನ್ನು ಸೇರಿಸಲು ಅನುಮತಿಸಿ.','Display the gift message as part of the order details table instead of a separate section' => 'ಉಡುಗೊರೆ ಸಂದೇಶವನ್ನು ಪ್ರತ್ಯೇಕ ವಿಭಾಗದ ಬದಲಿಗೆ ಆರ್ಡರ್ ವಿವರಗಳ ಕೋಷ್ಟಕದ ಭಾಗವಾಗಿ ಪ್ರದರ್ಶಿಸಿ.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ಈ ಆಯ್ಕೆಯು ಆರ್ಡರ್ ದೃಢೀಕರಣ ಪುಟ (ಧನ್ಯವಾದ ಪುಟ) ಮತ್ತು ಖಾತೆ ಪುಟಗಳು, ಇಮೇಲ್‌ಗಳು ಮತ್ತು ಪ್ಯಾಕಿಂಗ್ ಸ್ಲಿಪ್‌ಗಳಲ್ಲಿನ ಆರ್ಡರ್ ವಿವರಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ.','Account matching' => 'ಖಾತೆ ಹೊಂದಾಣಿಕೆ','Enable the account matching feature' => 'ಖಾತೆ ಹೊಂದಾಣಿಕೆ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ಗ್ರಾಹಕರ ಸಂಪರ್ಕ ವಿವರಗಳೊಂದಿಗೆ ಖಾತೆ ಈಗಾಗಲೇ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವಾಗ ಅತಿಥಿ ಗ್ರಾಹಕರ ಆದೇಶಗಳನ್ನು ಅವರ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಖಾತೆಯೊಂದಿಗೆ ಸಂಯೋಜಿಸಿ.','Display message when an account exists with the email address provided' => 'ಒದಗಿಸಲಾದ ಇಮೇಲ್ ವಿಳಾಸದೊಂದಿಗೆ ಖಾತೆ ಅಸ್ತಿತ್ವದಲ್ಲಿದ್ದರೆ ಸಂದೇಶವನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'ಖಾತೆ ರಚನೆ ಕ್ಷೇತ್ರಗಳನ್ನು ಅಧಿಸೂಚನೆ ಮತ್ತು ಲಾಗಿನ್ ಆಯ್ಕೆಯೊಂದಿಗೆ ಬದಲಾಯಿಸುತ್ತದೆ. ಕೆಲವು ಸಂದರ್ಭಗಳಲ್ಲಿ, ಗ್ರಾಹಕರ ಗೌಪ್ಯತೆಯನ್ನು ರಕ್ಷಿಸಲು ಈ ಆಯ್ಕೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲು ಶಿಫಾರಸು ಮಾಡಬಹುದು.','Dashboard' => 'ಡ್ಯಾಶ್‌ಬೋರ್ಡ್','Integrations' => 'ಸಂಯೋಜನೆಗಳು','License keys' => 'ಪರವಾನಗಿ ಕೀಲಿಗಳು','Visit our website for more information about our plugins and add-ons.' => 'ನಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳು ಮತ್ತು ಆಡ್-ಆನ್‌ಗಳ ಕುರಿತು ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ ನಮ್ಮ ವೆಬ್‌ಸೈಟ್‌ಗೆ ಭೇಟಿ ನೀಡಿ.','Order pay page' => 'ಆರ್ಡರ್ ಪಾವತಿ ಪುಟ','Order pay' => 'ಆರ್ಡರ್ ಪೇ','Enable order pay page optimizations' => 'ಆರ್ಡರ್ ಪೇ ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ಗ್ರಾಹಕರಿಂದ ಪಾವತಿ ಬಾಕಿ ಇರುವ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಆರ್ಡರ್‌ಗಳಿಗೆ ಆರ್ಡರ್ ಪೇ ಪುಟದ ವಿನ್ಯಾಸವನ್ನು ಬದಲಾಯಿಸುತ್ತದೆ.','Add widget areas to the order pay page' => 'ಆರ್ಡರ್ ಪಾವತಿ ಪುಟಕ್ಕೆ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಸೇರಿಸಿ','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ಈ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಆರ್ಡರ್ ಪೇ ಪುಟದಲ್ಲಿ ಟ್ರಸ್ಟ್ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ.','Thank you page & order details layout' => 'ಧನ್ಯವಾದಗಳು ಪುಟ &amp; ಆರ್ಡರ್ ವಿವರಗಳ ವಿನ್ಯಾಸ','Order details optimizations' => 'ಆರ್ಡರ್ ವಿವರಗಳ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳು','Enable thank you page and order details optimizations' => 'ಧನ್ಯವಾದ ಪುಟ ಮತ್ತು ಆರ್ಡರ್ ವಿವರಗಳ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Changes the layout of order details on the thank you page and account pages.' => 'ಧನ್ಯವಾದ ಪುಟ ಮತ್ತು ಖಾತೆ ಪುಟಗಳಲ್ಲಿ ಆರ್ಡರ್ ವಿವರಗಳ ವಿನ್ಯಾಸವನ್ನು ಬದಲಾಯಿಸುತ್ತದೆ.','Enable order details customizations on email notifications' => 'ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳಲ್ಲಿ ಆರ್ಡರ್ ವಿವರಗಳ ಕಸ್ಟಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳಲ್ಲಿ ಹೊಸ ವಿಭಾಗಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ ಮತ್ತು ವಿಭಾಗಗಳ ಕ್ರಮವನ್ನು ಬದಲಾಯಿಸಿ. ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳಲ್ಲಿನ ಆದೇಶ ವಿವರಗಳ ಶೈಲಿಗಳು ಬದಲಾಗದೆ ಉಳಿದಿವೆ.','Thank you page' => 'ಧನ್ಯವಾದಗಳು ಪುಟ','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ಈ ಆಯ್ಕೆಗಳು ಧನ್ಯವಾದ ಪುಟದ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ, ಇದನ್ನು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಅಥವಾ ಆರ್ಡರ್ ದೃಢೀಕರಣ ಪುಟಗಳು ಎಂದೂ ಕರೆಯುತ್ತಾರೆ.','Order details layout' => 'ಆರ್ಡರ್ ವಿವರಗಳ ವಿನ್ಯಾಸ','Display the order details with wide layout on the thank you page' => 'ಧನ್ಯವಾದ ಪುಟದಲ್ಲಿ ವಿಶಾಲ ವಿನ್ಯಾಸದೊಂದಿಗೆ ಆರ್ಡರ್ ವಿವರಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Add widget areas to the thank you page' => 'ಧನ್ಯವಾದ ಪುಟಕ್ಕೆ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಸೇರಿಸಿ','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'ಧನ್ಯವಾದ ಪುಟದಲ್ಲಿ ಟ್ರಸ್ಟ್ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಲು ಈ ವಿಜೆಟ್ ಪ್ರದೇಶಗಳನ್ನು ಬಳಸಲಾಗುತ್ತದೆ.','Order actions' => 'ಕ್ರಮಗಳ ಆದೇಶ','Choose in which position to display the order actions.' => 'ಕ್ರಮ ಕ್ರಮಗಳು ಯಾವ ಸ್ಥಾನದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Inside the order overview' => 'ಆದೇಶದ ಒಳಗಿನ ಅವಲೋಕನ','After the order overview' => 'ಆದೇಶದ ಅವಲೋಕನದ ನಂತರ','After order sections' => 'ಆದೇಶದ ನಂತರದ ವಿಭಾಗಗಳು','Order status' => 'ಆದೇಶ ಸ್ಥಿತಿ','Display the order status progress bar' => 'ಆದೇಶ ಸ್ಥಿತಿ ಪ್ರಗತಿ ಪಟ್ಟಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ','Choose in which position to display the section.' => 'ವಿಭಾಗವನ್ನು ಯಾವ ಸ್ಥಾನದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','After the order overview and payment instructions' => 'ಆರ್ಡರ್ ಅವಲೋಕನ ಮತ್ತು ಪಾವತಿ ಸೂಚನೆಗಳ ನಂತರ','Before the order items section' => 'ಆರ್ಡರ್ ಐಟಂಗಳ ವಿಭಾಗದ ಮೊದಲು','Inside the order items section' => 'ಆರ್ಡರ್ ಐಟಂಗಳ ವಿಭಾಗದ ಒಳಗೆ','After the order items section' => 'ಆರ್ಡರ್ ಐಟಂಗಳ ವಿಭಾಗದ ನಂತರ','On the sidebar' => 'ಸೈಡ್‌ಬಾರ್‌ನಲ್ಲಿ','Order downloads' => 'ಡೌನ್‌ಲೋಡ್‌ಗಳನ್ನು ಆರ್ಡರ್ ಮಾಡಿ','Gift message' => 'ಉಡುಗೊರೆ ಸಂದೇಶ','Tools' => 'ಪರಿಕರಗಳು','Troubleshooting' => 'ದೋಷನಿವಾರಣೆ','Debug options' => 'ಡೀಬಗ್ ಆಯ್ಕೆಗಳು','Debug mode' => 'ಡೀಬಗ್ ಮೋಡ್','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ಡೀಬಗ್ ಮೋಡ್ ಬಳಸುವುದರಿಂದ ವೆಬ್‌ಸೈಟ್ ಕಾರ್ಯಕ್ಷಮತೆಯ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ. ದೋಷನಿವಾರಣೆ ಮಾಡುವಾಗ ಮಾತ್ರ ಈ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿ.','Load unminified assets' => 'ಮಿನಿಫೈ ಮಾಡದ ಸ್ವತ್ತುಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ','Enhanced select fields' => 'ವರ್ಧಿತ ಆಯ್ದ ಕ್ಷೇತ್ರಗಳು','Fix automatic zoom-in on form fields' => 'ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತ ಜೂಮ್-ಇನ್ ಅನ್ನು ಸರಿಪಡಿಸಿ.','Set <code>font-size</code> inside form fields to 16px' => 'ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳ ಒಳಗೆ <code>font-size</code> 16px ಗೆ ಹೊಂದಿಸಿ.','Fluid Checkout' => 'ದ್ರವ ಚೆಕ್ಔಟ್','Settings' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Support' => 'ಬೆಂಬಲ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'ಹೆಚ್ಚಿನ ಆಯ್ಕೆಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು <a target="_blank" href="%s">PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ</a> .','(PRO)' => '(ಪ್ರೋ)','(experimental)' => '(ಪ್ರಾಯೋಗಿಕ)','Please verify your phone number.' => 'ದಯವಿಟ್ಟು ನಿಮ್ಮ ಫೋನ್ ಸಂಖ್ಯೆಯನ್ನು ಪರಿಶೀಲಿಸಿ.','The Bluehost Plugin' => 'ಬ್ಲೂಹೋಸ್ಟ್ ಪ್ಲಗಿನ್','Custom fields' => 'ಕಸ್ಟಮ್ ಕ್ಷೇತ್ರಗಳು','Enable custom shipping email field' => 'ಕಸ್ಟಮ್ ಶಿಪ್ಪಿಂಗ್ ಇಮೇಲ್ ಕ್ಷೇತ್ರವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, Bluehost ಪ್ಲಗಿನ್‌ನಿಂದ ಶಿಪ್ಪಿಂಗ್ ಇಮೇಲ್ ಕ್ಷೇತ್ರವನ್ನು ಚೆಕ್‌ಔಟ್ ಫಾರ್ಮ್‌ಗೆ ಸೇರಿಸಲಾಗುತ್ತದೆ.','Captcha Pro by BestWebSoft' => 'ಬೆಸ್ಟ್‌ವೆಬ್‌ಸಾಫ್ಟ್‌ನಿಂದ ಕ್ಯಾಪ್ಚಾ ಪ್ರೊ','Captcha position' => 'ಕ್ಯಾಪ್ಚಾ ಸ್ಥಾನ','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'ಕ್ಯಾಪ್ಚಾ ವಿಭಾಗವನ್ನು ಪ್ರದರ್ಶಿಸಲು ಸ್ಥಾನವನ್ನು ವಿವರಿಸಿ. ಆಯ್ಕೆ ಮಾಡಿದ ಕ್ಯಾಪ್ಚಾ ಪ್ರಕಾರವನ್ನು ಅವಲಂಬಿಸಿ ಕೆಲವು ಸ್ಥಾನಗಳು ಕಾರ್ಯನಿರ್ವಹಿಸದಿರಬಹುದು.','Selecting a pickup point is required before proceeding.' => 'ಮುಂದುವರಿಯುವ ಮೊದಲು ಪಿಕಪ್ ಪಾಯಿಂಟ್ ಆಯ್ಕೆ ಮಾಡುವ ಅಗತ್ಯವಿದೆ.','Pickup point' => 'ಪಿಕಪ್ ಪಾಯಿಂಟ್','Pickup point not selected yet.' => 'ಪಿಕಪ್ ಪಾಯಿಂಟ್ ಇನ್ನೂ ಆಯ್ಕೆಯಾಗಿಲ್ಲ.','Pickup point:' => 'ಪಿಕಪ್ ಪಾಯಿಂಟ್:','Mailchimp for WooCommerce' => 'WooCommerce ಗಾಗಿ ಮೇಲ್‌ಚಿಂಪ್','Subscribe checkbox' => 'ಚಂದಾದಾರರಾಗಿ ಚೆಕ್‌ಬಾಕ್ಸ್','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಚಂದಾದಾರಿಕೆ ಚೆಕ್‌ಬಾಕ್ಸ್‌ಗಾಗಿ ಸ್ಥಾನವನ್ನು ಓವರ್‌ರೈಡ್ ಮಾಡಿ ಮತ್ತು ಅದನ್ನು ಯಾವಾಗಲೂ ಸಂಪರ್ಕ ಹಂತದಲ್ಲಿ ಪ್ರದರ್ಶಿಸಿ.','Before Shipping Address' => 'ಶಿಪ್ಪಿಂಗ್ ಮೊದಲು ವಿಳಾಸ','(originally "%s")' => '(ಮೂಲತಃ &quot;%s&quot;)','After Shipping Address' => 'ಶಿಪ್ಪಿಂಗ್ ನಂತರದ ವಿಳಾಸ','Selecting a collection point is required when shipping with FermoPoint.' => 'ಫೆರ್ಮೊಪಾಯಿಂಟ್‌ನೊಂದಿಗೆ ಸಾಗಿಸುವಾಗ ಸಂಗ್ರಹಣಾ ಸ್ಥಳವನ್ನು ಆಯ್ಕೆ ಮಾಡುವ ಅಗತ್ಯವಿದೆ.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ಪರಿಶೀಲಿಸಿದರೆ ಬಳಕೆದಾರರಿಗೆ ಇಮೇಲ್‌ನಲ್ಲಿ ಟೈಪೊಗಳನ್ನು ತಿಳಿಸುತ್ತದೆ. (ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ವೈಶಿಷ್ಟ್ಯವನ್ನು ನೀಡುತ್ತಿರುವುದರಿಂದ ಈ ವೈಶಿಷ್ಟ್ಯವನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ. ಈ ಆಯ್ಕೆಗೆ ಬದಲಾವಣೆಗಳು ಪರಿಣಾಮ ಬೀರುವುದಿಲ್ಲ)','Enable Mail Check: (disabled feature)' => 'ಮೇಲ್ ಪರಿಶೀಲನೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ: (ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾದ ವೈಶಿಷ್ಟ್ಯ)','Carrier:' => 'ವಾಹಕ:','Sendinblue - WooCommerce Email Marketing' => 'ಸೆಂಡಿನ್‌ಬ್ಲೂ - WooCommerce ಇಮೇಲ್ ಮಾರ್ಕೆಟಿಂಗ್','Sign up checkbox position' => 'ಸೈನ್ ಅಪ್ ಚೆಕ್‌ಬಾಕ್ಸ್ ಸ್ಥಾನ','Move the sign up checkbox to the contact step' => 'ಸೈನ್ ಅಪ್ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಸಂಪರ್ಕ ಹಂತಕ್ಕೆ ಸರಿಸಿ.','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಸೆಂಡಿನ್‌ಬ್ಲೂ ಪ್ಲಗಿನ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ವ್ಯಾಖ್ಯಾನಿಸಲಾದ ಪ್ರದರ್ಶನ ಸ್ಥಳವನ್ನು ಲೆಕ್ಕಿಸದೆ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಸಂಪರ್ಕ ಹಂತಕ್ಕೆ ಸರಿಸಲಾಗುತ್ತದೆ.','Theme Betheme' => 'ಥೀಮ್ ಬೆಥೆಮ್','Checkout progress' => 'ಚೆಕ್ಔಟ್ ಪ್ರಗತಿ','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್ ಮತ್ತು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಪುಟಗಳಲ್ಲಿ ಬೆಥೆಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme Fennik' => 'ಥೀಮ್ ಫೆನಿಕ್','Breadcrumbs' => 'ಬ್ರೆಡ್ ತುಂಡುಗಳು','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಮತ್ತು ಫೂಟರ್ ಬಳಸುವಾಗ ಫೆನ್ನಿಕ್ ಥೀಮ್‌ನಿಂದ ಬ್ರೆಡ್‌ಕ್ರಂಬ್ಸ್ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme Go' => 'ಥೀಮ್ ಗೋ','My account layout' => 'ನನ್ನ ಖಾತೆ ವಿನ್ಯಾಸ','Enable wide layout on "My account" page.' => '&quot;ನನ್ನ ಖಾತೆ&quot; ಪುಟದಲ್ಲಿ ವಿಶಾಲ ವಿನ್ಯಾಸವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Theme Impreza' => 'ಥೀಮ್ ಇಂಪ್ರೆಜಾ','Header' => 'ಶಿರೋಲೇಖ','Spacing for site header at the checkout page (in pixels)' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಸೈಟ್ ಹೆಡರ್‌ಗಾಗಿ ಅಂತರ (ಪಿಕ್ಸೆಲ್‌ಗಳಲ್ಲಿ)','Only applicable when using the Impreza theme header at the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಇಂಪ್ರೆಜಾ ಥೀಮ್ ಹೆಡರ್ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','Theme Kapee' => 'ಥೀಮ್ ಕಪೀ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್ ಮತ್ತು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಪುಟಗಳಲ್ಲಿ ಕಪೀ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme Porto' => 'ಥೀಮ್ ಪೋರ್ಟೊ','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್ ಮತ್ತು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಪುಟಗಳಲ್ಲಿ ಪೋರ್ಟೊ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme Pressmart' => 'ಥೀಮ್ ಪ್ರೆಸ್‌ಮಾರ್ಟ್','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್ ಮತ್ತು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಪುಟಗಳಲ್ಲಿ ಪ್ರೆಸ್‌ಮಾರ್ಟ್ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme The Gem' => 'ಥೀಮ್ ದಿ ಜೆಮ್','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಮತ್ತು ಫೂಟರ್ ಬಳಸುವಾಗ ದಿ ಜೆಮ್ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Theme Woodmart' => 'ಥೀಮ್ ವುಡ್‌ಮಾರ್ಟ್','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಹೆಡರ್ ಮತ್ತು ಫೂಟರ್ ಬಳಸುವಾಗ ವುಡ್‌ಮಾರ್ಟ್ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Checkout options' => 'ಚೆಕ್ಔಟ್ ಆಯ್ಕೆಗಳು','Disable the theme checkout options' => 'ಥೀಮ್ ಚೆಕ್ಔಟ್ ಆಯ್ಕೆಗಳನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿ','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ಥೀಮ್‌ನಿಂದ ಸೇರಿಸಲಾದ ಉತ್ಪನ್ನ ಚಿತ್ರ, ಪ್ರಮಾಣ ಕ್ಷೇತ್ರ, ತೆಗೆದುಹಾಕು ಬಟನ್ ಮತ್ತು ಉತ್ಪನ್ನ ಪುಟಕ್ಕೆ ಲಿಂಕ್ ಆಯ್ಕೆಗಳನ್ನು ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗುತ್ತದೆ.','Theme Atomion' => 'ಥೀಮ್ ಆಟಮಿಯಾನ್','Order progress' => 'ಆದೇಶ ಪ್ರಗತಿ','Display order progress from the theme' => 'ಥೀಮ್‌ನಿಂದ ಆದೇಶದ ಪ್ರಗತಿಯನ್ನು ಪ್ರದರ್ಶಿಸಿ','Display the form field labels visible on the page' => 'ಪುಟದಲ್ಲಿ ಗೋಚರಿಸುವ ಫಾರ್ಮ್ ಫೀಲ್ಡ್ ಲೇಬಲ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','It is recommended to keep this option enabled for a better user experience.' => 'ಉತ್ತಮ ಬಳಕೆದಾರ ಅನುಭವಕ್ಕಾಗಿ ಈ ಆಯ್ಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.','Theme ZK Nito' => 'ಥೀಮ್ ZK ನಿಟೊ','Add extra fields to the checkout form' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ಗೆ ಹೆಚ್ಚುವರಿ ಕ್ಷೇತ್ರಗಳನ್ನು ಸೇರಿಸಿ.','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗಕ್ಕೆ ಹೆಚ್ಚುವರಿ ಶಿಪ್ಪಿಂಗ್ ಇಮೇಲ್ ಮತ್ತು ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು ಸೇರಿಸುತ್ತದೆ.','Go to the home page' => 'ಮುಖಪುಟಕ್ಕೆ ಹೋಗಿ','Skip to content' => 'ವಿಷಯಕ್ಕೆ ಹೋಗಿ','Create an account' => 'ಖಾತೆಯನ್ನು ತೆರೆಯಿರಿ','Log in to your account' => 'ನಿಮ್ಮ ಖಾತೆಗೆ ಲಾಗಿನ್ ಆಗಿ','Already have an account?' => 'ಈಗಾಗಲೇ ಖಾತೆ ಇದೆಯೇ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s ಆಗಿ ಲಾಗಿನ್ ಆಗಿದ್ದೀರಿ. <a href="%2$s">ಲಾಗ್ ಔಟ್ ಮಾಡಿ</a>','Your order has a total amount due of %s. No further payment is needed.' => 'ನಿಮ್ಮ ಆದೇಶದ ಒಟ್ಟು ಮೊತ್ತ %s ಬಾಕಿ ಇದೆ. ಯಾವುದೇ ಹೆಚ್ಚಿನ ಪಾವತಿ ಅಗತ್ಯವಿಲ್ಲ.','Close and continue with checkout' => 'ಮುಚ್ಚಿ ಮತ್ತು ಚೆಕ್ಔಟ್ ಮುಂದುವರಿಸಿ','Continue' => 'ಮುಂದುವರಿಸಿ','Parcel terminal' => 'ಪಾರ್ಸೆಲ್ ಟರ್ಮಿನಲ್','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ಈ ವಿಜೆಟ್ ಅನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ನಿಂದ ಬದಲಾಯಿಸಲಾಗಿದೆ.</p><p> ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಬಳಸುವಾಗ, ಚೆಕ್‌ಔಟ್ ಪುಟವು ಸರಿಯಾಗಿ ಕೆಲಸ ಮಾಡಲು ಮೂಲ WooCommerce ಶಾರ್ಟ್‌ಕೋಡ್ <code>[woocommerce_checkout]</code> ಅನ್ನು ಬಳಸಬೇಕಾಗುತ್ತದೆ.</p><p> ಹೆಚ್ಚಿನ ಮಾಹಿತಿಗಾಗಿ, ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ದಸ್ತಾವೇಜನ್ನು ಭೇಟಿ ಮಾಡಿ.</p>','Theme The7' => 'ಥೀಮ್ The7','Additional header sections' => 'ಹೆಚ್ಚುವರಿ ಹೆಡರ್ ವಿಭಾಗಗಳು','Output additional header sections if enabled in the theme settings.' => 'ಥೀಮ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಸಕ್ರಿಯಗೊಳಿಸಿದ್ದರೆ ಹೆಚ್ಚುವರಿ ಹೆಡರ್ ವಿಭಾಗಗಳನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','More information' => 'ಹೆಚ್ಚಿನ ಮಾಹಿತಿ','Pick a Locker' => 'ಲಾಕರ್ ಆಯ್ಕೆಮಾಡಿ','Page template' => 'ಪುಟ ಟೆಂಪ್ಲೇಟ್','Use `Order confirmation` page template for block-based themes' => 'ಬ್ಲಾಕ್-ಆಧಾರಿತ ಥೀಮ್‌ಗಳಿಗಾಗಿ `ಆರ್ಡರ್ ದೃಢೀಕರಣ` ಪುಟ ಟೆಂಪ್ಲೇಟ್ ಬಳಸಿ','Only applies when using a block-based theme.' => 'ಬ್ಲಾಕ್-ಆಧಾರಿತ ಥೀಮ್ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','WooCommerce Stripe Gateway' => 'WooCommerce ಸ್ಟ್ರೈಪ್ ಗೇಟ್‌ವೇ','Payment form' => 'ಪಾವತಿ ಫಾರ್ಮ್','Apply styles to the Stripe payment form fields' => 'ಸ್ಟ್ರೈಪ್ ಪಾವತಿ ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳಿಗೆ ಶೈಲಿಗಳನ್ನು ಅನ್ವಯಿಸಿ','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಪ್ಲಗಿನ್‌ನೊಂದಿಗೆ ಹೊಂದಾಣಿಕೆಗಾಗಿ ಆಪ್ಟಿಮೈಸ್ ಮಾಡಲಾದ ಶೈಲಿಗಳನ್ನು ಅನ್ವಯಿಸುತ್ತದೆ. ನೀವು ಸ್ಟ್ರೈಪ್ ಪಾವತಿ ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳಿಗೆ ಕಸ್ಟಮ್ ಶೈಲಿಗಳನ್ನು ಬಳಸುತ್ತಿದ್ದರೆ ನೀವು ಇದನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಬೇಕಾಗಬಹುದು.','Theme Nyture' => 'ಥೀಮ್ ನೈಚರ್','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಬಳಸುವಾಗ ನೈಚರ್ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'ಅಂಗಡಿ ನಿರ್ವಾಹಕರು ಹಸ್ತಚಾಲಿತವಾಗಿ ರಚಿಸಿದ ಅಥವಾ ಚೆಕ್‌ಔಟ್ ಸಮಯದಲ್ಲಿ ಪೂರ್ಣಗೊಳ್ಳದ ಆರ್ಡರ್‌ಗಳಿಗೆ ಪಾವತಿಗಳನ್ನು ಮಾಡಲು ಗ್ರಾಹಕರಿಗೆ ಅನುಮತಿಸುತ್ತದೆ.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'ಕ್ವಾಡ್‌ಲೇಯರ್‌ಗಳ WooCommerce ಚೆಕ್‌ಔಟ್ ಮ್ಯಾನೇಜರ್ ಪ್ಲಗಿನ್ ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ಗೆ ಹೊಂದಿಕೆಯಾಗುವುದಿಲ್ಲ.','Company name field for billing address' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಕ್ಕಾಗಿ ಕಂಪನಿ ಹೆಸರಿನ ಕ್ಷೇತ್ರ','Change visibility for the company name field for the billing address section on the checkout form.' => 'ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್‌ನಲ್ಲಿ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗಕ್ಕೆ ಕಂಪನಿಯ ಹೆಸರಿನ ಕ್ಷೇತ್ರದ ಗೋಚರತೆಯನ್ನು ಬದಲಾಯಿಸಿ.','Theme Bookshelf' => 'ಥೀಮ್ ಪುಸ್ತಕದ ಕಪಾಟು','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಬಳಸುವಾಗ ಬುಕ್‌ಶೆಲ್ಫ್ ಥೀಮ್‌ನಿಂದ ಚೆಕ್ಔಟ್ ಹಂತಗಳ ವಿಭಾಗವನ್ನು ಔಟ್‌ಪುಟ್ ಮಾಡಿ.','Account password' => 'ಖಾತೆಯ ಪಾಸ್‌ವರ್ಡ್','An account will be created with the information provided at checkout when completing the order.' => 'ಆರ್ಡರ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸುವಾಗ ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ಒದಗಿಸಲಾದ ಮಾಹಿತಿಯೊಂದಿಗೆ ಖಾತೆಯನ್ನು ರಚಿಸಲಾಗುತ್ತದೆ.','Choose the style of the progress bar.' => 'ಪ್ರಗತಿ ಪಟ್ಟಿಯ ಶೈಲಿಯನ್ನು ಆರಿಸಿ.','Bars' => 'ಬಾರ್‌ಗಳು','Theme Ireca' => 'ಥೀಮ್ ಐರೆಕಾ','WooCommerce page layout' => 'WooCommerce ಪುಟ ವಿನ್ಯಾಸ','Force wide layout on WooCommerce pages' => 'WooCommerce ಪುಟಗಳಲ್ಲಿ ಬಲವಂತದ ವಿಶಾಲ ವಿನ್ಯಾಸ','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ಇದು WooCommerce ಪುಟಗಳಲ್ಲಿ ವಿಷಯ ವಿಭಾಗವು ತುಂಬಾ ಕಿರಿದಾಗಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಇದರಲ್ಲಿ ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್, ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಲಾಗಿದೆ, ಆರ್ಡರ್ ಪೇ ಮತ್ತು ಖಾತೆ ಪುಟಗಳು ಸೇರಿವೆ.','WooCommerce Smart Coupons' => 'WooCommerce ಸ್ಮಾರ್ಟ್ ಕೂಪನ್‌ಗಳು','Position on checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಸ್ಥಾನ','Choose where to display the available coupons section on the checkout page.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ಲಭ್ಯವಿರುವ ಕೂಪನ್‌ಗಳ ವಿಭಾಗವನ್ನು ಎಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ.','Before the progress bar' => 'ಪ್ರಗತಿ ಪಟ್ಟಿಯ ಮೊದಲು','After the progress bar' => 'ಪ್ರಗತಿ ಪಟ್ಟಿಯ ನಂತರ','Before coupon codes section' => 'ಕೂಪನ್ ಕೋಡ್‌ಗಳ ವಿಭಾಗಕ್ಕಿಂತ ಮೊದಲು','Format phone numbers according to the rules for each country.' => 'ಪ್ರತಿಯೊಂದು ದೇಶಕ್ಕೂ ನಿಯಮಗಳ ಪ್ರಕಾರ ಫೋನ್ ಸಂಖ್ಯೆಗಳನ್ನು ಫಾರ್ಮ್ಯಾಟ್ ಮಾಡಿ.','Use precise phone number validation' => 'ನಿಖರವಾದ ಫೋನ್ ಸಂಖ್ಯೆಯ ದೃಢೀಕರಣವನ್ನು ಬಳಸಿ','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ಇದು ಪ್ರಾಯೋಗಿಕ ವೈಶಿಷ್ಟ್ಯವಾಗಿದ್ದು, ಎಲ್ಲಾ ಸೆಟಪ್‌ಗಳಲ್ಲಿ ನಿರೀಕ್ಷೆಯಂತೆ ಕಾರ್ಯನಿರ್ವಹಿಸದಿರಬಹುದು. ಇದನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಬಳಸಿ.','Phone number validation types used when precise validation is enabled.' => 'ನಿಖರವಾದ ದೃಢೀಕರಣವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಬಳಸಲಾಗುವ ಫೋನ್ ಸಂಖ್ಯೆ ದೃಢೀಕರಣದ ಪ್ರಕಾರಗಳು.','Mobile' => 'ಮೊಬೈಲ್','Fixed line' => 'ಸ್ಥಿರ ಮಾರ್ಗ','Toll free' => 'ಟೋಲ್ ಫ್ರೀ','Or' => 'ಅಥವಾ','Contact' => 'ಸಂಪರ್ಕಿಸಿ','Multi step' => 'ಬಹು ಹಂತ','2 columns' => '2 ಕಾಲಮ್‌ಗಳು','1 column' => '1 ಕಾಲಮ್','Before checkout steps' => 'ಚೆಕ್ಔಟ್ ಹಂತಗಳ ಮೊದಲು','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 ಕಾಲಮ್&quot;</em> ಚೆಕ್ಔಟ್ ವಿನ್ಯಾಸವನ್ನು ಬಳಸುವಾಗ ಈ ಆಯ್ಕೆಯನ್ನು ಯಾವಾಗಲೂ <em>&quot;ಚೆಕ್ಔಟ್ ಹಂತಗಳ ಮೊದಲು&quot;</em> ಎಂದು ಹೊಂದಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಡೆಸ್ಕ್‌ಟಾಪ್ ವೀಕ್ಷಣೆಗೂ ಅನ್ವಯಿಸುತ್ತದೆ.','Position for the extra order summary section on mobile.' => 'ಮೊಬೈಲ್‌ನಲ್ಲಿ ಹೆಚ್ಚುವರಿ ಆರ್ಡರ್ ಸಾರಾಂಶ ವಿಭಾಗದ ಸ್ಥಾನ.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;ಸೈಟ್ ಹೆಡರ್‌ನಲ್ಲಿ&quot;</em> ಆಯ್ಕೆಯು ಅಡ್ಡಿ-ಮುಕ್ತ ಹೆಡರ್ ಬಳಸುವಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','On the site header (requires distraction-free header)' => 'ಸೈಟ್ ಹೆಡರ್‌ನಲ್ಲಿ (ಗೊಂದಲ-ಮುಕ್ತ ಹೆಡರ್ ಅಗತ್ಯವಿದೆ)','Initial state for the expansible order summary section on mobile.' => 'ಮೊಬೈಲ್‌ನಲ್ಲಿ ವಿಸ್ತರಿಸಬಹುದಾದ ಆರ್ಡರ್ ಸಾರಾಂಶ ವಿಭಾಗದ ಆರಂಭಿಕ ಸ್ಥಿತಿ.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'ನಿಯಂತ್ರಕ ಅವಶ್ಯಕತೆಗಳಿಂದಾಗಿ ಇದನ್ನು ಈ ಕೆಳಗಿನ ದೇಶಗಳಿಗೆ <em>ವಿಸ್ತರಿಸಿದಂತೆ</em> ಹೊಂದಿಸಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ: <strong>ಜರ್ಮನಿ</strong> , <strong>ಆಸ್ಟ್ರಿಯಾ</strong> , <strong>ಸ್ವಿಟ್ಜರ್‌ಲ್ಯಾಂಡ್</strong> , <strong>ನೆದರ್‌ಲ್ಯಾಂಡ್ಸ್</strong> , <strong>ಪೋಲೆಂಡ್</strong> , <strong>ಬೆಲ್ಜಿಯಂ</strong> ಮತ್ತು <strong>ಫ್ರಾನ್ಸ್</strong> .','Collapsed' => 'ಕುಗ್ಗಿಸಲಾಗಿದೆ','Expanded' => 'ವಿಸ್ತರಿಸಲಾಗಿದೆ','Do not show' => 'ತೋರಿಸಬೇಡಿ','yes' => 'ಹೌದು','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವು ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗದ ನಂತರ ಕಾಣಿಸಿಕೊಂಡರೆ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು &quot;ಅಗತ್ಯ&quot; ಎಂದು ಹೊಂದಿಸಿದರೆ ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು &quot;ಅಗತ್ಯ&quot; ಎಂದು ಒತ್ತಾಯಿಸಬಹುದು. ಆ ಆಯ್ಕೆಯನ್ನು ಪರಿಶೀಲಿಸಿದಾಗ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವನ್ನು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಕ್ಕೆ ನಕಲಿಸಬಹುದೆಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಇದು ಅಗತ್ಯವಾಗಿರುತ್ತದೆ, ಇಲ್ಲದಿದ್ದರೆ ಗ್ರಾಹಕರು ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗದಿರಬಹುದು.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗವು ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ ವಿಭಾಗದ ಮೊದಲು ಪ್ರದರ್ಶಿಸಲ್ಪಟ್ಟಿದ್ದರೆ ಮತ್ತು ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು &quot;ಅಗತ್ಯ&quot; ಎಂದು ಹೊಂದಿಸಿದ್ದರೆ ಬಿಲ್ಲಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರವನ್ನು &quot;ಅಗತ್ಯ&quot; ಎಂದು ಒತ್ತಾಯಿಸಬಹುದು. ಆ ಆಯ್ಕೆಯನ್ನು ಪರಿಶೀಲಿಸಿದಾಗ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸವನ್ನು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಕ್ಕೆ ನಕಲಿಸಬಹುದೆಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ಇದು ಅಗತ್ಯವಾಗಿರುತ್ತದೆ, ಇಲ್ಲದಿದ್ದರೆ ಗ್ರಾಹಕರು ಚೆಕ್ಔಟ್ ಫಾರ್ಮ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗದಿರಬಹುದು.','Settings profiles' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪ್ರೊಫೈಲ್‌ಗಳು','Settings profile' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪ್ರೊಫೈಲ್','You do not have permission to perform this action.' => 'ಈ ಕ್ರಿಯೆಯನ್ನು ಮಾಡಲು ನಿಮಗೆ ಅನುಮತಿ ಇಲ್ಲ.','You do not have permission to activate plugins.' => 'ಪ್ಲಗಿನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ನಿಮಗೆ ಅನುಮತಿ ಇಲ್ಲ.','Missing plugin.' => 'ಪ್ಲಗಿನ್ ಕಾಣೆಯಾಗಿದೆ.','Plugin activated.' => 'ಪ್ಲಗಿನ್ ಸಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','The following changes will be applied:' => 'ಈ ಕೆಳಗಿನ ಬದಲಾವಣೆಗಳನ್ನು ಅನ್ವಯಿಸಲಾಗುತ್ತದೆ:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ 5.0 ರಿಂದ, ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ವಿಭಿನ್ನವಾಗಿ ಉಳಿಸಲಾಗುತ್ತದೆ. ಅಗತ್ಯವಿದ್ದರೆ ಹಿಂದಿನ ಆವೃತ್ತಿಗಳಿಗೆ ಡೌನ್‌ಗ್ರೇಡ್ ಮಾಡಲು ಅನುಮತಿಸಲು ಲೆಗಸಿ ಆಯ್ಕೆಗಳನ್ನು ಇನ್ನೂ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'ನಿಮ್ಮ ಅಂಗಡಿಯು ಸುಮಾರು 2 ವಾರಗಳಿಂದ ಹೊಸ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತಿದೆ, ಇದರಿಂದ ನೀವು ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಸಂಗ್ರಹವಾಗಿರುವ ಲೆಗಸಿ ಆಯ್ಕೆಗಳನ್ನು ಸ್ವಚ್ಛಗೊಳಿಸಬಹುದು. ಸ್ವಚ್ಛಗೊಳಿಸಿದ ನಂತರ, ನೀವು ಪ್ಲಗಿನ್‌ನ ಹಿಂದಿನ ಆವೃತ್ತಿಗಳಿಗೆ ಡೌನ್‌ಗ್ರೇಡ್ ಮಾಡಬೇಕಾದರೆ ಅದು ಎಲ್ಲಾ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಡೀಫಾಲ್ಟ್ ಮೌಲ್ಯಗಳನ್ನು ಬಳಸುತ್ತದೆ ಎಂಬುದನ್ನು ದಯವಿಟ್ಟು ಗಮನಿಸಿ.','Fluid Checkout settings cleanup' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಸ್ವಚ್ಛಗೊಳಿಸುವಿಕೆ','Delete leftover options' => 'ಉಳಿದ ಆಯ್ಕೆಗಳನ್ನು ಅಳಿಸಿ','Help us improve Fluid Checkout' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಅನ್ನು ಸುಧಾರಿಸಲು ನಮಗೆ ಸಹಾಯ ಮಾಡಿ','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'ವೇಗವಾದ ಬೆಂಬಲವನ್ನು ಪಡೆಯಲು ಮತ್ತು ಹೊಂದಾಣಿಕೆಯನ್ನು ಸುಧಾರಿಸಲು ಮತ್ತು ಪರಿಣಾಮವನ್ನು ಅಳೆಯಲು ನಮಗೆ ಸಹಾಯ ಮಾಡಲು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನೊಂದಿಗೆ ಅನಾಮಧೇಯ ಸೈಟ್ ಪರಿಸರ ವರದಿಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಿ. ಯಾವುದೇ ಗ್ರಾಹಕ, ಬಳಕೆದಾರ ಅಥವಾ ಸೂಕ್ಷ್ಮ ಡೇಟಾವನ್ನು ಸೇರಿಸಲಾಗಿಲ್ಲ. ಪರಿಕರಗಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ನೀವು ಯಾವುದೇ ಸಮಯದಲ್ಲಿ ಏನು ಹಂಚಿಕೊಳ್ಳಬೇಕೆಂದು ಆಯ್ಕೆ ಮಾಡಬಹುದು.','Enable site environment reports' => 'ಸೈಟ್ ಪರಿಸರ ವರದಿಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Review settings' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಪರಿಶೀಲಿಸಿ','This preview has expired. Reload the admin page to start a new preview.' => 'ಈ ಪೂರ್ವವೀಕ್ಷಣೆ ಅವಧಿ ಮುಗಿದಿದೆ. ಹೊಸ ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ಪ್ರಾರಂಭಿಸಲು ನಿರ್ವಾಹಕ ಪುಟವನ್ನು ಮರುಲೋಡ್ ಮಾಡಿ.','Preview expired' => 'ಪೂರ್ವವೀಕ್ಷಣೆ ಅವಧಿ ಮುಗಿದಿದೆ','Orders cannot be placed in the preview.' => 'ಪೂರ್ವವೀಕ್ಷಣೆಯಲ್ಲಿ ಆರ್ಡರ್‌ಗಳನ್ನು ಇರಿಸಲಾಗುವುದಿಲ್ಲ.','Logging in is not available in the preview.' => 'ಪೂರ್ವವೀಕ್ಷಣೆಯಲ್ಲಿ ಲಾಗಿನ್ ಆಗುವುದು ಲಭ್ಯವಿಲ್ಲ.','Accounts cannot be created in the preview.' => 'ಪೂರ್ವವೀಕ್ಷಣೆಯಲ್ಲಿ ಖಾತೆಗಳನ್ನು ರಚಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.','Requests to other sites are blocked in the preview.' => 'ಇತರ ಸೈಟ್‌ಗಳಿಗೆ ವಿನಂತಿಗಳನ್ನು ಪೂರ್ವವೀಕ್ಷಣೆಯಲ್ಲಿ ನಿರ್ಬಂಧಿಸಲಾಗಿದೆ.','Processing…' => 'ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲಾಗುತ್ತಿದೆ...','Something went wrong. Please try again.' => 'ಏನೋ ತಪ್ಪಾಗಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Activate plugin' => 'ಪ್ಲಗಿನ್ ಸಕ್ರಿಯಗೊಳಿಸಿ','Fluid Checkout PRO - The complete checkout package' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಪ್ರೊ - ಸಂಪೂರ್ಣ ಚೆಕ್ಔಟ್ ಪ್ಯಾಕೇಜ್','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'ಎಲ್ಲಾ PRO ವೈಶಿಷ್ಟ್ಯಗಳು + ಎಲ್ಲಾ ಆಡ್-ಆನ್‌ಗಳು, ಒಂದೇ ಬೆಲೆ. ವಿನ್ಯಾಸ ಟೆಂಪ್ಲೇಟ್‌ಗಳು, ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿದ ಕಾರ್ಟ್ ಮತ್ತು ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಪುಟಗಳು, ಖಾತೆ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ಇನ್ನೂ ಹೆಚ್ಚಿನವು.','Optimized order pay page' => 'ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿದ ಆರ್ಡರ್ ಪಾವತಿ ಪುಟ','Express checkout buttons from supported payment methods' => 'ಬೆಂಬಲಿತ ಪಾವತಿ ವಿಧಾನಗಳಿಂದ ಎಕ್ಸ್‌ಪ್ರೆಸ್ ಚೆಕ್‌ಔಟ್ ಬಟನ್‌ಗಳು','Delayed account creation' => 'ಖಾತೆ ರಚನೆ ವಿಳಂಬವಾಗಿದೆ','Address autocomplete with Google Maps APIs' => 'Google Maps API ಗಳೊಂದಿಗೆ ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆ','Multiple saved addresses with the address book' => 'ವಿಳಾಸ ಪುಸ್ತಕದೊಂದಿಗೆ ಬಹು ಉಳಿಸಿದ ವಿಳಾಸಗಳು','EU-VAT assistant' => 'EU-VAT ಸಹಾಯಕ','Hide this section' => 'ಈ ವಿಭಾಗವನ್ನು ಮರೆಮಾಡಿ','Learn more' => 'ಇನ್ನಷ್ಟು ತಿಳಿಯಿರಿ','Get early access' => 'ಆರಂಭಿಕ ಪ್ರವೇಶವನ್ನು ಪಡೆಯಿರಿ','Activate add-on' => 'ಆಡ್-ಆನ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Get more out of your checkout journey' => 'ನಿಮ್ಮ ಚೆಕ್ಔಟ್ ಪ್ರಯಾಣದಿಂದ ಹೆಚ್ಚಿನದನ್ನು ಪಡೆಯಿರಿ','Test API key' => 'API ಕೀಲಿಯನ್ನು ಪರೀಕ್ಷಿಸಿ','Guided setup' => 'ಮಾರ್ಗದರ್ಶಿ ಸೆಟಪ್','Options' => 'ಆಯ್ಕೆಗಳು','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">ಚೆಕ್ಔಟ್ ಆಯ್ಕೆಗಳಲ್ಲಿ</a> ವಿನ್ಯಾಸ ಮತ್ತು ವಿನ್ಯಾಸವನ್ನು ಹೊಂದಿಸಿ.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'ಅತಿಥಿ ಚೆಕ್ಔಟ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ ಮತ್ತು/ಅಥವಾ <a href="%s">ಗ್ರಾಹಕ ಖಾತೆಗಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು</a> ಪರಿಶೀಲಿಸಿ.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ಆಪ್ಟಿಮೈಸ್ ಮಾಡಿದ <a href="%1$s">ಕಾರ್ಟ್ ಅನ್ನು</a> ಸಕ್ರಿಯಗೊಳಿಸಿ, <a href="%2$s">ಧನ್ಯವಾದಗಳು</a> ಮತ್ತು <a href="%3$s">ಪಾವತಿ ಪುಟಗಳನ್ನು ಆದೇಶಿಸಿ</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google ನಕ್ಷೆಗಳಿಂದ <a href="%s">ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು</a> ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">ವಿಳಾಸ ಪುಸ್ತಕದೊಂದಿಗೆ</a> ಬಹು ಉಳಿಸಿದ ವಿಳಾಸಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'ನೀವು ಸ್ಥಾಪಿಸಿರುವ ಥೀಮ್ ಅಥವಾ ಇತರ ಪ್ಲಗಿನ್‌ಗಳಿಗೆ ಯಾವುದೇ <a href="%s">ಏಕೀಕರಣ ಆಯ್ಕೆಗಳು</a> ಲಭ್ಯವಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸಿ.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'ವೇಗವಾದ ಬೆಂಬಲವನ್ನು ಪಡೆಯಿರಿ ಮತ್ತು ಹೊಂದಾಣಿಕೆಯನ್ನು ಸುಧಾರಿಸಲು ಮತ್ತು ಪರಿಣಾಮವನ್ನು ಅಳೆಯಲು ನಮಗೆ ಸಹಾಯ ಮಾಡಿ. ಪರಿಕರಗಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ <a href="%s">ಬಳಕೆಯ ಟ್ರ್ಯಾಕಿಂಗ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ</a> .','Missing settings tab.' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಟ್ಯಾಬ್ ಕಾಣೆಯಾಗಿದೆ.','Getting started' => 'ಪ್ರಾರಂಭಿಸುವುದು','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>ಅದ್ಭುತ! ನಿಮ್ಮ ಚೆಕ್ಔಟ್ ಪುಟವು ಈಗ ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ಚಾಲನೆಯಲ್ಲಿದೆ.</strong> ಪ್ರಾರಂಭಿಸಲು ಕೆಲವು ಹಂತಗಳು ಇಲ್ಲಿವೆ:','Completed' => 'ಪೂರ್ಣಗೊಂಡಿದೆ','Preview report data' => 'ವರದಿ ಡೇಟಾವನ್ನು ಪೂರ್ವವೀಕ್ಷಿಸಿ','Send now' => 'ಈಗ ಕಳುಹಿಸಿ','Auto-detect' => 'ಸ್ವಯಂ-ಪತ್ತೆಹಚ್ಚುವಿಕೆ','Afrikaans' => 'ಆಫ್ರಿಕಾನ್ಸ್','Albanian' => 'ಅಲ್ಬೇನಿಯನ್','Amharic' => 'ಅಂಹರಿಕ್','Arabic' => 'ಅರೇಬಿಕ್','Armenian' => 'ಅರ್ಮೇನಿಯನ್','Azerbaijani' => 'ಅಜೆರ್ಬೈಜಾನಿ','Basque' => 'ಬಾಸ್ಕ್','Belarusian' => 'ಬೆಲರೂಸಿಯನ್','Bengali' => 'ಬಂಗಾಳಿ','Bosnian' => 'ಬೋಸ್ನಿಯನ್','Bulgarian' => 'ಬಲ್ಗೇರಿಯನ್','Burmese' => 'ಬರ್ಮೀಸ್','Catalan' => 'ಕೆಟಲಾನ್','Chinese' => 'ಚೈನೀಸ್','Chinese (Simplified)' => 'ಚೈನೀಸ್ (ಸರಳೀಕೃತ)','Chinese (Hong Kong)' => 'ಚೈನೀಸ್ (ಹಾಂಗ್ ಕಾಂಗ್)','Chinese (Traditional)' => 'ಚೈನೀಸ್ (ಸಾಂಪ್ರದಾಯಿಕ)','Croatian' => 'ಕ್ರೊಯೇಷಿಯನ್','Czech' => 'ಜೆಕ್','Danish' => 'ಡ್ಯಾನಿಶ್','Dutch' => 'ಡಚ್','English' => 'ಇಂಗ್ಲೀಷ್','English (Australian)' => 'ಇಂಗ್ಲಿಷ್ (ಆಸ್ಟ್ರೇಲಿಯನ್)','English (Great Britain)' => 'ಇಂಗ್ಲಿಷ್ (ಗ್ರೇಟ್ ಬ್ರಿಟನ್)','Estonian' => 'ಎಸ್ಟೋನಿಯನ್','Farsi' => 'ಫಾರ್ಸಿ','Finnish' => 'ಫಿನ್ನಿಶ್','Filipino' => 'ಫಿಲಿಪಿನೋ','French' => 'ಫ್ರೆಂಚ್','French (Canadian)' => 'ಫ್ರೆಂಚ್ (ಕೆನಡಿಯನ್)','Galician' => 'ಗ್ಯಾಲಿಶಿಯನ್','Georgian' => 'ಜಾರ್ಜಿಯನ್','German' => 'ಜರ್ಮನ್','Greek' => 'ಗ್ರೀಕ್','Gujarati' => 'ಗುಜರಾತಿ','Hebrew' => 'ಹೀಬ್ರೂ','Hindi' => 'ಹಿಂದಿ','Hungarian' => 'ಹಂಗೇರಿಯನ್','Icelandic' => 'ಐಸ್ಲ್ಯಾಂಡಿಕ್','Indonesian' => 'ಇಂಡೋನೇಷಿಯನ್','Italian' => 'ಇಟಾಲಿಯನ್','Japanese' => 'ಜಪಾನೀಸ್','Kannada' => 'ಕನ್ನಡ','Kazakh' => 'ಕಝಕ್','Khmer' => 'ಖಮೇರ್','Korean' => 'ಕೊರಿಯನ್','Kyrgyz' => 'ಕಿರ್ಗಿಜ್','Lao' => 'ಲಾವೋ','Latvian' => 'ಲಾಟ್ವಿಯನ್','Lithuanian' => 'ಲಿಥುವೇನಿಯನ್','Macedonian' => 'ಮೆಸಿಡೋನಿಯನ್','Malay' => 'ಮಲಯ','Malayalam' => 'ಮಲಯಾಳಂ','Marathi' => 'ಮರಾಠಿ','Mongolian' => 'ಮಂಗೋಲಿಯನ್','Nepali' => 'ನೇಪಾಳಿ','Norwegian' => 'ನಾರ್ವೇಜಿಯನ್','Polish' => 'ಪೋಲಿಷ್','Portuguese' => 'ಪೋರ್ಚುಗೀಸ್','Portuguese (Brazil)' => 'ಪೋರ್ಚುಗೀಸ್ (ಬ್ರೆಜಿಲ್)','Portuguese (Portugal)' => 'ಪೋರ್ಚುಗೀಸ್ (ಪೋರ್ಚುಗಲ್)','Punjabi' => 'ಪಂಜಾಬಿ','Romanian' => 'ರೊಮೇನಿಯನ್','Russian' => 'ರಷ್ಯನ್','Serbian' => 'ಸರ್ಬಿಯನ್','Sinhalese' => 'ಸಿಂಹಳೀಯರು','Slovak' => 'ಸ್ಲೋವಾಕ್','Slovenian' => 'ಸ್ಲೊವೇನಿಯನ್','Spanish' => 'ಸ್ಪ್ಯಾನಿಷ್','Spanish (Latin America)' => 'ಸ್ಪ್ಯಾನಿಷ್ (ಲ್ಯಾಟಿನ್ ಅಮೆರಿಕ)','Swahili' => 'ಸ್ವಾಹಿಲಿ','Swedish' => 'ಸ್ವೀಡಿಷ್','Tamil' => 'ತಮಿಳು','Telugu' => 'ತೆಲುಗು','Thai' => 'ಥಾಯ್','Turkish' => 'ಟರ್ಕಿಶ್','Ukrainian' => 'ಉಕ್ರೇನಿಯನ್','Urdu' => 'ಉರ್ದು','Vietnamese' => 'ವಿಯೆಟ್ನಾಮೀಸ್','Zulu' => 'ಜುಲು','Google address autocomplete' => 'Google ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣತೆ','Google Places API version' => 'Google ಸ್ಥಳಗಳ API ಆವೃತ್ತಿ','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API ನ ಯಾವ ಆವೃತ್ತಿಯನ್ನು ಬಳಸಬೇಕೆಂದು ಆರಿಸಿ. ಸಾಧ್ಯವಾದಷ್ಟು ಬೇಗ ಹೊಸ Places API ಗೆ ಬದಲಾಯಿಸಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'ಮಾರ್ಚ್ 1, 2025 ರಿಂದ ಜಾರಿಗೆ ಬರುವಂತೆ &quot;Places API (ಹೊಸದು)&quot; ಅನ್ನು ಬಳಸಲು ನಾವು ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ, Google &quot;Places API (ಲೆಗಸಿ)&quot; ಆವೃತ್ತಿಯನ್ನು ಲೆಗಸಿ ಸ್ಥಿತಿಗೆ ಸರಿಸುತ್ತದೆ, ಅಂದರೆ ನೀವು ಇನ್ನು ಮುಂದೆ ಹೊಸ API ಕೀಗಳಿಗಾಗಿ ಈ ಸೇವೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗುವುದಿಲ್ಲ ಮತ್ತು API ನ ಆ ಆವೃತ್ತಿಯು ಅಂತಿಮವಾಗಿ ಇನ್ನು ಮುಂದೆ ಲಭ್ಯವಿರುವುದಿಲ್ಲ. ಈಗಾಗಲೇ ಲೆಗಸಿ API ಅನ್ನು ಬಳಸುತ್ತಿರುವ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಖಾತೆಗಳು ಯಾವುದೇ ಅಡೆತಡೆಗಳಿಲ್ಲದೆ ಕಾರ್ಯನಿರ್ವಹಿಸುವುದನ್ನು ಮುಂದುವರಿಸಬಹುದು.','(Recommended)' => '(ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ)','Google API key' => 'ಗೂಗಲ್ API ಕೀ','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'ನಿಮ್ಮ Google API ಕೀಯನ್ನು ಅಂಟಿಸಿ ಮತ್ತು ಪರೀಕ್ಷಾ ಬಟನ್ ಬಳಸಿ ಅದು ಈ ವೆಬ್‌ಸೈಟ್‌ಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ. ಕೀ ಮಾನ್ಯವಾಗಿದೆಯೇ ಮತ್ತು ನಿಮ್ಮ ಡೊಮೇನ್‌ಗೆ ಅನುಮತಿಸಲಾಗಿದೆಯೇ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ, ಇಲ್ಲದಿದ್ದರೆ ವಿಳಾಸ ಕ್ಷೇತ್ರವು ಗ್ರಾಹಕರು ತಮ್ಮ ಆರ್ಡರ್‌ಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸುವುದನ್ನು ತಡೆಯುವುದನ್ನು ತಡೆಯಬಹುದು.','Enable Google address autocomplete' => 'Google ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable address autocompletion using the Google Maps APIs.' => 'Google Maps API ಗಳನ್ನು ಬಳಸಿಕೊಂಡು ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Google API language' => 'Google API ಭಾಷೆ','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'ಈ ಭಾಷೆಯನ್ನು Google Places API ವಿಳಾಸ ಸಲಹೆಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ವಿಳಾಸಗಳನ್ನು ಸಹ ಈ ಭಾಷೆಯಲ್ಲಿ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸಲಾಗುತ್ತದೆ.','Result types' => 'ಫಲಿತಾಂಶದ ಪ್ರಕಾರಗಳು','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ಯಾವುದೇ ರೀತಿಯ ಫಲಿತಾಂಶಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಖಾಲಿ ಬಿಡಿ, ಅದು ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ ಹೊಂದಾಣಿಕೆಯ ಫಲಿತಾಂಶಗಳನ್ನು ನೀಡುತ್ತದೆ. <a href="%s" target="_blank">ಹೆಚ್ಚಿನ ವಿವರಗಳಿಗಾಗಿ ದಸ್ತಾವೇಜನ್ನು ನೋಡಿ</a> .<br> ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣತೆ ಕ್ಷೇತ್ರಗಳಿಗೆ ಹಿಂತಿರುಗಲು 5 ರೀತಿಯ ವಿಳಾಸ ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ಬೆಂಬಲಿತ ಪ್ರಕಾರಗಳ</a> ಕುರಿತು ಇನ್ನಷ್ಟು ತಿಳಿದುಕೊಳ್ಳಲು Google ನಕ್ಷೆಗಳ ದಸ್ತಾವೇಜನ್ನು ಭೇಟಿ ಮಾಡಿ.','Result types (Legacy API)' => 'ಫಲಿತಾಂಶ ಪ್ರಕಾರಗಳು (ಲೆಗಸಿ API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'ಸ್ಥಳಗಳ API (ಲೆಗಸಿ) ಬಳಸುವಾಗ ಯಾವ ರೀತಿಯ ವಿಳಾಸ ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳನ್ನು ಹಿಂತಿರುಗಿಸಬೇಕು.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">ಬೆಂಬಲಿತ ಪ್ರಕಾರಗಳ</a> ಕುರಿತು ಇನ್ನಷ್ಟು ತಿಳಿದುಕೊಳ್ಳಲು ಲೆಗಸಿ Google Places API ನ ದಸ್ತಾವೇಜನ್ನು ಭೇಟಿ ಮಾಡಿ.','Company fields' => 'ಕಂಪನಿ ಕ್ಷೇತ್ರಗಳು','Enable autocomplete for the company name if available' => 'ಲಭ್ಯವಿದ್ದರೆ ಕಂಪನಿಯ ಹೆಸರಿಗೆ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google Maps API ಗಳಿಂದ ಹಿಂತಿರುಗಿದಾಗ ಕಂಪನಿ ಹೆಸರಿನ ಮಾಹಿತಿಯೊಂದಿಗೆ ಕಂಪನಿ ಕ್ಷೇತ್ರದ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Business search' => 'ವ್ಯಾಪಾರ ಹುಡುಕಾಟ','Enable search for businesses in the company field' => 'ಕಂಪನಿ ಕ್ಷೇತ್ರದಲ್ಲಿ ವ್ಯವಹಾರಗಳ ಹುಡುಕಾಟವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'ಕಂಪನಿ ಕ್ಷೇತ್ರದಲ್ಲಿ ಟೈಪ್ ಮಾಡುವಾಗ ವ್ಯವಹಾರಕ್ಕೆ ಸಂಬಂಧಿಸಿದ ವಿಳಾಸಗಳ ಸಲಹೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ, ನಂತರ ಸಲಹೆಗಳಿಂದ ವ್ಯವಹಾರವನ್ನು ಆಯ್ಕೆ ಮಾಡಿದಾಗ ಎಲ್ಲಾ ವಿಳಾಸಗಳ ಕ್ಷೇತ್ರಗಳನ್ನು ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸಿ.','Company result types' => 'ಕಂಪನಿ ಫಲಿತಾಂಶದ ಪ್ರಕಾರಗಳು','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ಸ್ವಯಂಪೂರ್ಣ ಕಂಪನಿ ಕ್ಷೇತ್ರಗಳಿಗೆ ಹಿಂತಿರುಗಲು 5 ರೀತಿಯ ವಿಳಾಸ ಹುಡುಕಾಟ ಫಲಿತಾಂಶಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ.<br> ಶಿಫಾರಸು ಮಾಡಲಾದ ಮೌಲ್ಯವು <code>establishment</code> , ಇದು ಹೆಚ್ಚಿನ ರೀತಿಯ ವ್ಯವಹಾರಗಳನ್ನು ಒಳಗೊಂಡಿದೆ.<br> ವ್ಯವಹಾರಗಳಿಗೆ ಸಂಬಂಧಿಸದ ಫಲಿತಾಂಶಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಯಾವುದೇ ರೀತಿಯ ಫಲಿತಾಂಶಗಳನ್ನು ಸ್ವೀಕರಿಸಲು ಖಾಲಿ ಬಿಡಿ.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">ಬೆಂಬಲಿತ ಪ್ರಕಾರಗಳ</a> ಕುರಿತು ಇನ್ನಷ್ಟು ತಿಳಿದುಕೊಳ್ಳಲು Google ನಕ್ಷೆಗಳ ದಸ್ತಾವೇಜನ್ನು ಭೇಟಿ ಮಾಡಿ.','Google logo' => 'ಗೂಗಲ್ ಲೋಗೋ','Show text and logo "Powered by Google"' => '&quot;Google ನಿಂದ ನಡೆಸಲ್ಪಡುತ್ತಿದೆ&quot; ಎಂಬ ಪಠ್ಯ ಮತ್ತು ಲೋಗೋವನ್ನು ತೋರಿಸಿ.','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ಗುರುತು ಹಾಕಿದಾಗ, ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣತೆ ಸಲಹೆಗಳ ಪೆಟ್ಟಿಗೆಯ ಕೆಳಭಾಗದಲ್ಲಿ &quot;Google ನಿಂದ ನಡೆಸಲ್ಪಡುತ್ತಿದೆ&quot; ಎಂಬ ಪಠ್ಯ ಮತ್ತು ಲೋಗೋವನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Brasil API address autocomplete' => 'ಬ್ರೆಸಿಲ್ API ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣತೆ','Brasil API' => 'ಬ್ರೆಸಿಲ್ API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ಕ್ಷೇತ್ರಗಳಿಗೆ ಬ್ರೆಸಿಲ್ API ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/ಪೋಸ್ಟ್‌ಕೋಡ್ ಕ್ಷೇತ್ರವನ್ನು ಬಳಸಿಕೊಂಡು ವಿಳಾಸಗಳನ್ನು ಹಿಂಪಡೆಯಲು ಮತ್ತು ಸ್ವಯಂತುಂಬಿಸಲು ಬ್ರೆಸಿಲ್ API ಬಳಸಿ. ಬ್ರೆಜಿಲಿಯನ್ ವಿಳಾಸಗಳಿಗೆ ಮಾತ್ರ ಸಂಬಂಧಿಸಿದೆ.','API version' => 'API ಆವೃತ್ತಿ','Choose which version of the Brasil API CEP method to use.' => 'ಬ್ರೆಸಿಲ್ API CEP ವಿಧಾನದ ಯಾವ ಆವೃತ್ತಿಯನ್ನು ಬಳಸಬೇಕೆಂದು ಆರಿಸಿ.','Address book migration' => 'ವಿಳಾಸ ಪುಸ್ತಕ ವಲಸೆ','WooCommerce addresses' => 'WooCommerce ವಿಳಾಸಗಳು','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce ನಿಂದ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಶಿಪ್ಪಿಂಗ್ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಗಳನ್ನು ಗ್ರಾಹಕರ ವಿಳಾಸ ಪುಸ್ತಕಕ್ಕೆ ನಕಲಿಸಿ.','Enable the address book feature' => 'ವಿಳಾಸ ಪುಸ್ತಕ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ಗ್ರಾಹಕರಿಗೆ ಬಹು ವಿಳಾಸಗಳನ್ನು ಉಳಿಸಲು ಮತ್ತು ಸಾಗಣೆ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್‌ಗಾಗಿ ಬಳಸಬೇಕಾದ ಡೀಫಾಲ್ಟ್ ವಿಳಾಸವನ್ನು ವ್ಯಾಖ್ಯಾನಿಸಲು ಅನುಮತಿಸಿ.','Address labels' => 'ವಿಳಾಸ ಲೇಬಲ್‌ಗಳು','Allow customers to add a custom label for each address' => 'ಪ್ರತಿ ವಿಳಾಸಕ್ಕೂ ಕಸ್ಟಮ್ ಲೇಬಲ್ ಸೇರಿಸಲು ಗ್ರಾಹಕರಿಗೆ ಅನುಮತಿಸಿ.','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'ವಿಳಾಸ ಲೇಬಲ್‌ಗಳು ಗ್ರಾಹಕರು ತಮ್ಮ ಉಳಿಸಿದ ವಿಳಾಸಗಳ ನಡುವೆ ವ್ಯತ್ಯಾಸವನ್ನು ಗುರುತಿಸಲು ಸುಲಭಗೊಳಿಸುತ್ತದೆ (ಅಂದರೆ: &quot;ಅಮ್ಮನ ಮನೆ&quot;). ವಿಳಾಸ ಲೇಬಲ್‌ಗಳು ಗ್ರಾಹಕರಿಗೆ ಖಾಸಗಿಯಾಗಿರುತ್ತವೆ ಮತ್ತು ಆರ್ಡರ್ ವಿವರಗಳ ಪುಟ ಅಥವಾ ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ಪ್ರದರ್ಶಿಸಲಾಗುವುದಿಲ್ಲ ಅಥವಾ ಮುದ್ರಿಸಲಾಗುವುದಿಲ್ಲ.','Display layout' => 'ಪ್ರದರ್ಶನ ವಿನ್ಯಾಸ','Choose how saved addresses are displayed at checkout and on the cart.' => 'ಉಳಿಸಿದ ವಿಳಾಸಗಳನ್ನು ಚೆಕ್ಔಟ್ ಮತ್ತು ಕಾರ್ಟ್‌ನಲ್ಲಿ ಹೇಗೆ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ ಎಂಬುದನ್ನು ಆರಿಸಿ.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ಚೆಕ್ಔಟ್ ಮತ್ತು ಕಾರ್ಟ್‌ನಲ್ಲಿ ಅನ್ವಯಿಸುತ್ತದೆ. ಖಾತೆ ಪುಟದಲ್ಲಿ ಉಳಿಸಲಾದ ವಿಳಾಸಗಳು ಯಾವಾಗಲೂ ಕಾರ್ಡ್‌ಗಳ ವಿನ್ಯಾಸವನ್ನು ಬಳಸುತ್ತವೆ.','Address cards' => 'ವಿಳಾಸ ಕಾರ್ಡ್‌ಗಳು','Address list' => 'ವಿಳಾಸ ಪಟ್ಟಿ','Dropdown field' => 'ಡ್ರಾಪ್‌ಡೌನ್ ಕ್ಷೇತ್ರ','Address search' => 'ವಿಳಾಸ ಹುಡುಕಾಟ','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ಗ್ರಾಹಕರು ಕನಿಷ್ಠ ಈ ಸಂಖ್ಯೆಯ ಉಳಿಸಿದ ವಿಳಾಸಗಳು ಲಭ್ಯವಿರುವಾಗ ಮುಂಭಾಗದಲ್ಲಿ ವಿಳಾಸ ಹುಡುಕಾಟ ಫಿಲ್ಟರ್ ಅನ್ನು ತೋರಿಸಿ.','Not used when display layout is set to dropdown field.' => 'ಪ್ರದರ್ಶನ ವಿನ್ಯಾಸವನ್ನು ಡ್ರಾಪ್‌ಡೌನ್ ಕ್ಷೇತ್ರಕ್ಕೆ ಹೊಂದಿಸಿದಾಗ ಬಳಸಲಾಗುವುದಿಲ್ಲ.','Addresses' => 'ವಿಳಾಸಗಳು','Enable cart page optimizations to see more options' => 'ಹೆಚ್ಚಿನ ಆಯ್ಕೆಗಳನ್ನು ನೋಡಲು ಕಾರ್ಟ್ ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Sticky order summary' => 'ಸ್ಟಿಕಿ ಆರ್ಡರ್ ಸಾರಾಂಶ','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ಕಾರ್ಟ್ ಪುಟದಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್‌ಗಳ ವಿಭಾಗವನ್ನು ಎಲ್ಲಿ ಪ್ರದರ್ಶಿಸಬೇಕು ಎಂಬುದನ್ನು ಆಯ್ಕೆಮಾಡಿ. AJAX ಕಾರ್ಟ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಮತ್ತು WooCommerce ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್‌ಗಳ ಬಳಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','Layout of cross-sell' => 'ಅಡ್ಡ-ಮಾರಾಟದ ವಿನ್ಯಾಸ','Cross-sells displayed' => 'ಕ್ರಾಸ್-ಸೆಲ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗಿದೆ','Items' => 'ವಸ್ತುಗಳು','Cart page optimization' => 'ಕಾರ್ಟ್ ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್','Give your cart the same clear, conversion-focused layout as your checkout.' => 'ನಿಮ್ಮ ಕಾರ್ಟ್‌ಗೆ ನಿಮ್ಮ ಚೆಕ್‌ಔಟ್‌ನಂತೆಯೇ ಸ್ಪಷ್ಟ, ಪರಿವರ್ತನೆ-ಕೇಂದ್ರಿತ ವಿನ್ಯಾಸವನ್ನು ನೀಡಿ.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'ಸ್ಥಿರವಾದ ಖರೀದಿ ಪ್ರಯಾಣಕ್ಕಾಗಿ ಕಾರ್ಟ್ ವಿನ್ಯಾಸವನ್ನು ಚೆಕ್ಔಟ್ ಪುಟಕ್ಕೆ ಹೊಂದಿಸಿ.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'ಕಾರ್ಟ್ ಅನ್ನು ಯಾವಾಗಲೂ ಹಿನ್ನೆಲೆಯಲ್ಲಿ ನವೀಕರಿಸುತ್ತಿರಿ, ಪ್ರಮಾಣಗಳು ಬದಲಾದಾಗ ಪೂರ್ಣ ಪುಟ ಮರುಲೋಡ್ ಆಗುವುದಿಲ್ಲ.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ಕೂಪನ್ ಕೋಡ್‌ಗಳು, ಶಿಪ್ಪಿಂಗ್ ಮತ್ತು ಕ್ರಾಸ್-ಸೆಲ್‌ಗಳನ್ನು ಅವು ಉತ್ತಮವಾಗಿ ಪರಿವರ್ತಿಸುವ ಸ್ಥಳದಲ್ಲಿ ಇರಿಸಿ.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'ಸ್ಕ್ರೋಲ್ ಮಾಡುವಾಗ ಆರ್ಡರ್ ಸಾರಾಂಶವು ಗೋಚರಿಸುವಂತೆ ಇರಿಸಿ ಮತ್ತು ಖರೀದಿದಾರರಿಗೆ ಧೈರ್ಯದ ಅಗತ್ಯವಿರುವಲ್ಲಿ ನಂಬಿಕೆಯ ಚಿಹ್ನೆಗಳನ್ನು ಸೇರಿಸಿ.','Columns' => 'ಕಾಲಮ್‌ಗಳು','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'ಚೆಕ್ಔಟ್ ಹಂತಗಳು, ಆರ್ಡರ್ ಸಾರಾಂಶ ಮತ್ತು ಇತರ ವಿಭಾಗಗಳಿಗೆ ಸಾಮಾನ್ಯ ಶೈಲಿಗಳು. ಇತರ ಚೆಕ್ಔಟ್, ಕಾರ್ಟ್, ಧನ್ಯವಾದಗಳು (ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಲಾಗಿದೆ) ಮತ್ತು ಆರ್ಡರ್ ಪುಟಗಳನ್ನು ವೀಕ್ಷಿಸಲು ಅನ್ವಯಿಸುತ್ತದೆ.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;ಸ್ಪ್ಲಿಟ್&quot;</em> ವಿನ್ಯಾಸ ಟೆಂಪ್ಲೇಟ್‌ನೊಂದಿಗೆ <em>&quot;1 ಕಾಲಮ್&quot;</em> ವಿನ್ಯಾಸವನ್ನು ಬಳಸುವಾಗ, ಪುಟ ಸೈಡ್‌ಬಾರ್ ವಿಜೆಟ್ ಪ್ರದೇಶವು ಸಕ್ರಿಯವಾಗಿದ್ದರೆ ಮಾತ್ರ ಬಲ ಕಾಲಮ್ ಅನ್ನು ತೋರಿಸಲಾಗುತ್ತದೆ (ಚೆಕ್‌ಔಟ್ ಸೈಡ್‌ಬಾರ್, ಕಾರ್ಟ್ ಸೈಡ್‌ಬಾರ್, ಅಥವಾ ಆರ್ಡರ್ ಸ್ವೀಕರಿಸಿದ ಸೈಡ್‌ಬಾರ್). ಇಲ್ಲದಿದ್ದರೆ ಪುಟವು ಸ್ಪ್ಲಿಟ್ ಶೈಲಿಗಳೊಂದಿಗೆ ಒಂದೇ ಕಾಲಮ್ ಆಗಿ ಉಳಿಯುತ್ತದೆ.','Split column background' => 'ಕಾಲಮ್ ಹಿನ್ನೆಲೆಯನ್ನು ವಿಭಜಿಸಿ','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'ಸ್ಪ್ಲಿಟ್ ವಿನ್ಯಾಸ ದ್ವಿತೀಯ ಕಾಲಮ್‌ಗೆ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಆರಿಸಿ. ಆರ್ಡರ್ ಸಾರಾಂಶ ಹಿನ್ನೆಲೆ ಬಣ್ಣವನ್ನು ಬಳಸಲು ಖಾಲಿ ಬಿಡಿ.','Page templates' => 'ಪುಟ ಟೆಂಪ್ಲೇಟ್‌ಗಳು','Checkout template' => 'ಚೆಕ್ಔಟ್ ಟೆಂಪ್ಲೇಟ್','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಕಡಿಮೆ ಗೊಂದಲಗಳಿಗೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">ಕಾರ್ಟ್ ತ್ಯಜಿಸುವಿಕೆಯ ಕುರಿತು ಸಂಶೋಧನೆಯನ್ನು ಓದಿ</a> .','Sticky progress bar' => 'ಸ್ಟಿಕಿ ಪ್ರೋಗ್ರೆಸ್ ಬಾರ್','Progress bar style' => 'ಪ್ರಗತಿ ಪಟ್ಟಿಯ ಶೈಲಿ','Order totals' => 'ಒಟ್ಟು ಆರ್ಡರ್‌ಗಳು','Background color' => 'ಹಿನ್ನೆಲೆ ಬಣ್ಣ','Action link' => 'ಕ್ರಿಯೆಯ ಲಿಂಕ್','Mobile order summary' => 'ಮೊಬೈಲ್ ಆರ್ಡರ್ ಸಾರಾಂಶ','Mobile initial state' => 'ಮೊಬೈಲ್ ಆರಂಭಿಕ ಸ್ಥಿತಿ','Enable editing cart items at checkout' => 'ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ಕಾರ್ಟ್ ಐಟಂಗಳನ್ನು ಸಂಪಾದಿಸುವುದನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ಗ್ರಾಹಕರು ಉತ್ಪನ್ನದ ಪ್ರಮಾಣವನ್ನು ಬದಲಾಯಿಸಲು ಅಥವಾ ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ ನೇರವಾಗಿ ವಸ್ತುಗಳನ್ನು ತೆಗೆದುಹಾಕಲು ಅನುಮತಿಸಿ.','Cart item errors' => 'ಕಾರ್ಟ್ ಐಟಂ ದೋಷಗಳು','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ಚೆಕ್ಔಟ್ ಅಥವಾ ಕಾರ್ಟ್ ಪುಟಗಳಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್ ಅನ್ನು ಪ್ರತ್ಯೇಕ ವಿಭಾಗವಾಗಿ ಪ್ರದರ್ಶಿಸಿದಾಗ ಮತ್ತು WooCommerce ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಕೂಪನ್ ಕೋಡ್‌ಗಳ ಬಳಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದ್ದರೆ ಮಾತ್ರ ಅನ್ವಯಿಸುತ್ತದೆ.','Coupon codes position' => 'ಕೂಪನ್ ಕೋಡ್‌ಗಳ ಸ್ಥಾನ','Apply coupon button' => 'ಕೂಪನ್ ಬಟನ್ ಅನ್ವಯಿಸಿ','Select style of the "apply coupon" button.' => '&quot;ಕೂಪನ್ ಅನ್ವಯಿಸು&quot; ಬಟನ್‌ನ ಶೈಲಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ.','Address line 2' => 'ವಿಳಾಸ ಸಾಲು 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ಈ ಸೆಟ್ಟಿಂಗ್ ಅನ್ನು ಚೆಕ್ಔಟ್ ಮತ್ತು ಸ್ಥಳೀಯ ಪಿಕಪ್ ವಿಭಾಗಗಳ ನಡುವೆ ಹಂಚಿಕೊಳ್ಳಲಾಗಿದೆ. ಸ್ಥಳೀಯ ಪಿಕಪ್ ವಿಭಾಗದಲ್ಲಿ, ಹಡಗು/ಪಿಕಪ್ ಆಯ್ಕೆಯು ಶಿಪ್ಪಿಂಗ್ ವಿಧಾನ ವಿಭಾಗದ ಒಳಗೆ (ವಿಳಾಸದ ಮೊದಲು) ಅಥವಾ ಪ್ರತ್ಯೇಕ ವಿಭಾಗವಾಗಿ (ನಂತರ) ತೋರಿಸಬೇಕೆ ಎಂದು ಸಹ ನಿರ್ಧರಿಸುತ್ತದೆ.','Customer accounts' => 'ಗ್ರಾಹಕ ಖಾತೆಗಳು','Guest checkout' => 'ಅತಿಥಿ ಚೆಕ್ಔಟ್','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce ಖಾತೆಗಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪುಟದಿಂದ ಅತಿಥಿ ಚೆಕ್‌ಔಟ್, ಲಾಗಿನ್ ಮತ್ತು ಖಾತೆ ರಚನೆ ಆಯ್ಕೆಗಳು. ನಿಮ್ಮ ಅನುಕೂಲಕ್ಕಾಗಿ ಅವುಗಳನ್ನು ಇಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಆದ್ದರಿಂದ ನೀವು ಪ್ರತಿ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪ್ರೊಫೈಲ್‌ಗೆ ವಿಭಿನ್ನ ಮೌಲ್ಯಗಳನ್ನು ಬಳಸಬಹುದು.','Allow customers to checkout without an account' => 'ಖಾತೆಯಿಲ್ಲದೆ ಗ್ರಾಹಕರು ಚೆಕ್ಔಟ್ ಮಾಡಲು ಅನುಮತಿಸಿ','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರಿಗೆ ಖಾತೆಯನ್ನು ರಚಿಸಲು ಅಥವಾ ಲಾಗಿನ್ ಮಾಡಲು ಕೇಳಲಾಗುವುದಿಲ್ಲ ಎಂದು <strong>ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ</strong> , ಇದು ಪರಿವರ್ತನೆ ದರಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.','When disabled, customers must log in or create an account to complete the purchase.' => 'ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಗ್ರಾಹಕರು ಖರೀದಿಯನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಲಾಗಿನ್ ಆಗಬೇಕು ಅಥವಾ ಖಾತೆಯನ್ನು ರಚಿಸಬೇಕು.','Login at checkout' => 'ಚೆಕ್ಔಟ್ ನಲ್ಲಿ ಲಾಗಿನ್ ಮಾಡಿ','Enable log-in during checkout' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಲಾಗಿನ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Show a link for returning customers to log in from the checkout page.' => 'ಹಿಂದಿರುಗುವ ಗ್ರಾಹಕರಿಗೆ ಚೆಕ್ಔಟ್ ಪುಟದಿಂದ ಲಾಗಿನ್ ಆಗಲು ಲಿಂಕ್ ತೋರಿಸಿ.','Account creation' => 'ಖಾತೆ ರಚನೆ','Allow customers to create an account during checkout' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರು ಖಾತೆಯನ್ನು ರಚಿಸಲು ಅನುಮತಿಸಿ','Customers can create an account before placing their order.' => 'ಗ್ರಾಹಕರು ತಮ್ಮ ಆರ್ಡರ್ ಮಾಡುವ ಮೊದಲು ಖಾತೆಯನ್ನು ರಚಿಸಬಹುದು.','Allow customers to create an account from the My account page' => 'ಗ್ರಾಹಕರು ನನ್ನ ಖಾತೆ ಪುಟದಿಂದ ಖಾತೆಯನ್ನು ರಚಿಸಲು ಅನುಮತಿಸಿ.','Customers can register a new account from the My account page.' => 'ಗ್ರಾಹಕರು ನನ್ನ ಖಾತೆ ಪುಟದಿಂದ ಹೊಸ ಖಾತೆಯನ್ನು ನೋಂದಾಯಿಸಿಕೊಳ್ಳಬಹುದು.','Username' => 'ಬಳಕೆದಾರಹೆಸರು','Generate from customer\'s name' => 'ಗ್ರಾಹಕರ ಹೆಸರಿನಿಂದ ರಚಿಸಿ','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರನ್ನು ಬಳಕೆದಾರಹೆಸರನ್ನು ಆಯ್ಕೆ ಮಾಡಲು ಕೇಳದಿರಲು <strong>ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ</strong> , ಇದು ಪರಿವರ್ತನೆ ದರಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ಗ್ರಾಹಕರ ಹೆಸರಿನಿಂದ ಅಥವಾ ಹೆಸರನ್ನು ಬಳಸಲು ಸಾಧ್ಯವಾಗದಿದ್ದಾಗ ಇಮೇಲ್ ವಿಳಾಸದಿಂದ ಬಳಕೆದಾರಹೆಸರನ್ನು ರಚಿಸಲಾಗುತ್ತದೆ.','Password' => 'ಪಾಸ್ವರ್ಡ್','Send password setup link' => 'ಪಾಸ್‌ವರ್ಡ್ ಸೆಟಪ್ ಲಿಂಕ್ ಕಳುಹಿಸಿ','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರು ಪಾಸ್‌ವರ್ಡ್ ಹೊಂದಿಸಲು ಕೇಳದಂತೆ <strong>ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ</strong> , ಇದು ಪರಿವರ್ತನೆ ದರಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಬಹುದು.','Customers receive an email to create their password securely.' => 'ಗ್ರಾಹಕರು ತಮ್ಮ ಪಾಸ್‌ವರ್ಡ್ ಅನ್ನು ಸುರಕ್ಷಿತವಾಗಿ ರಚಿಸಲು ಇಮೇಲ್ ಅನ್ನು ಸ್ವೀಕರಿಸುತ್ತಾರೆ.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'ನೋಂದಾಯಿತ ಗ್ರಾಹಕರು ಲಾಗಿನ್ ಆಗದೆಯೇ ಚೆಕ್ಔಟ್ ಅನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಮತ್ತು ಸಂಪರ್ಕ ವಿವರಗಳು ಹೊಂದಿಕೆಯಾದಾಗ ಅವರ ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಖಾತೆಯೊಂದಿಗೆ ಆರ್ಡರ್ ಅನ್ನು ಸಂಯೋಜಿಸಲು ಅವಕಾಶ ಮಾಡಿಕೊಡಿ.','Existing account message' => 'ಅಸ್ತಿತ್ವದಲ್ಲಿರುವ ಖಾತೆ ಸಂದೇಶ','Let customers create an account after placing their order, from the thank you page.' => 'ಗ್ರಾಹಕರು ತಮ್ಮ ಆರ್ಡರ್ ಮಾಡಿದ ನಂತರ ಧನ್ಯವಾದ ಪುಟದಿಂದ ಖಾತೆಯನ್ನು ರಚಿಸಲಿ.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ಅತಿಥಿ ಚೆಕ್ಔಟ್ ಮತ್ತು ಖಾತೆ ಹೊಂದಾಣಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಈ ವಿಭಾಗದಲ್ಲಿ ಆಯ್ಕೆಗಳು ಲಭ್ಯವಿರುತ್ತವೆ. ವಿಳಂಬವಾದ ಖಾತೆ ರಚನೆಯನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಲು ಮೇಲಿನ ಎರಡೂ ವೈಶಿಷ್ಟ್ಯಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Enable delayed account creation' => 'ವಿಳಂಬಿತ ಖಾತೆ ರಚನೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'ಅತಿಥಿ ಚೆಕ್ಔಟ್ ಮತ್ತು ಖಾತೆ ಹೊಂದಾಣಿಕೆ ಎರಡನ್ನೂ ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ವಿಳಂಬಿತ ಖಾತೆ ರಚನೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Section position' => 'ವಿಭಾಗದ ಸ್ಥಾನ','Before customer details section' => 'ಗ್ರಾಹಕರ ವಿವರಗಳ ವಿಭಾಗಕ್ಕೆ ಮೊದಲು','After customer details section' => 'ಗ್ರಾಹಕರ ವಿವರಗಳ ವಿಭಾಗದ ನಂತರ','Account creation benefits' => 'ಖಾತೆ ರಚನೆಯ ಪ್ರಯೋಜನಗಳು','Leaving the field empty will display the default text.' => 'ಕ್ಷೇತ್ರವನ್ನು ಖಾಲಿ ಬಿಟ್ಟರೆ ಡೀಫಾಲ್ಟ್ ಪಠ್ಯವನ್ನು ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ.','Inline buttons' => 'ಇನ್‌ಲೈನ್ ಬಟನ್‌ಗಳು','Required fields' => 'ಅಗತ್ಯವಿರುವ ಕ್ಷೇತ್ರಗಳು','Enable gift message fields at checkout' => 'ಚೆಕ್ಔಟ್‌ನಲ್ಲಿ ಉಡುಗೊರೆ ಸಂದೇಶ ಕ್ಷೇತ್ರಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Expanded gift message' => 'ವಿಸ್ತೃತ ಉಡುಗೊರೆ ಸಂದೇಶ','Display gift message field always expanded' => 'ಉಡುಗೊರೆ ಸಂದೇಶ ಕ್ಷೇತ್ರವನ್ನು ಯಾವಾಗಲೂ ವಿಸ್ತರಿಸಲಾಗುತ್ತದೆ.','Gift message in order details' => 'ಆರ್ಡರ್ ವಿವರಗಳಲ್ಲಿ ಉಡುಗೊರೆ ಸಂದೇಶ','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ಈ ವಿಭಾಗದಲ್ಲಿ ಪ್ರಸ್ತುತ ಯಾವುದೇ ಏಕೀಕರಣಗಳು ಲಭ್ಯವಿಲ್ಲ. ಪ್ರತಿಯೊಂದು ಪ್ಲಗಿನ್ ಮತ್ತು ಥೀಮ್‌ಗೆ ಸಂಬಂಧಿಸಿದ ಆಯ್ಕೆಗಳು ಆ ಪ್ಲಗಿನ್ ಅಥವಾ ಥೀಮ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಮಾತ್ರ ಇಲ್ಲಿ ಗೋಚರಿಸುತ್ತವೆ.','Phone fields' => 'ಫೋನ್ ಕ್ಷೇತ್ರಗಳು','Field visibility' => 'ಕ್ಷೇತ್ರದ ಗೋಚರತೆ','Field position' => 'ಕ್ಷೇತ್ರದ ಸ್ಥಾನ','Phone country code & validation' => 'ಫೋನ್ ದೇಶದ ಕೋಡ್ ಮತ್ತು ದೃಢೀಕರಣ','Country' => 'ದೇಶ','Enable country on phone fields' => 'ಫೋನ್ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ದೇಶವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Filter countries for shipping or billing' => 'ಶಿಪ್ಪಿಂಗ್ ಅಥವಾ ಬಿಲ್ಲಿಂಗ್‌ಗಾಗಿ ದೇಶಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ಪ್ರತಿ ಫೋನ್ ಕ್ಷೇತ್ರದಲ್ಲಿನ ದೇಶದ ಆಯ್ಕೆದಾರರನ್ನು ನಿಮ್ಮ ಅಂಗಡಿಯಲ್ಲಿ ಸಾಗಣೆ ಅಥವಾ ಬಿಲ್ಲಿಂಗ್‌ಗೆ ಅನುಮತಿಸಲಾದ ದೇಶಗಳಿಗೆ ಮಿತಿಗೊಳಿಸಿ.','Validation' => 'ಮೌಲ್ಯೀಕರಣ','Enable simple validation based on country rules' => 'ದೇಶದ ನಿಯಮಗಳ ಆಧಾರದ ಮೇಲೆ ಸರಳ ಮೌಲ್ಯೀಕರಣವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ','Checks that the phone number is valid for the selected country, including country code and length.' => 'ದೇಶದ ಕೋಡ್ ಮತ್ತು ಉದ್ದ ಸೇರಿದಂತೆ ಆಯ್ಕೆಮಾಡಿದ ದೇಶಕ್ಕೆ ಫೋನ್ ಸಂಖ್ಯೆ ಮಾನ್ಯವಾಗಿದೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುತ್ತದೆ.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'ಆಯ್ಕೆಮಾಡಿದ ದೇಶಕ್ಕೆ ಆ ಸಂಖ್ಯೆಯು ಮಾನ್ಯವಾದ ಮೊಬೈಲ್, ಸ್ಥಿರ ದೂರವಾಣಿ ಅಥವಾ ಇತರ ಸ್ವೀಕೃತ ಪ್ರಕಾರವಾಗಿದೆಯೇ ಎಂಬುದನ್ನು ಕಟ್ಟುನಿಟ್ಟಾಗಿ ಪರಿಶೀಲಿಸಿ. ಕೆಲವು ಮಾನ್ಯ ಸಂಖ್ಯೆಗಳನ್ನು ತಿರಸ್ಕರಿಸಬಹುದು.','Validation types' => 'ಮೌಲ್ಯೀಕರಣದ ಪ್ರಕಾರಗಳು','Placeholders' => 'ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳು','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'ಈ ಸಮಯದಲ್ಲಿ ನಿರ್ವಹಿಸಲು ಯಾವುದೇ ಪರವಾನಗಿ ಕೀಗಳಿಲ್ಲ. ಪರವಾನಗಿ ಪಡೆದ ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಪ್ಲಗಿನ್ ಅಥವಾ ಆಡ್-ಆನ್ ಸಕ್ರಿಯವಾಗಿದ್ದಾಗ ಪರವಾನಗಿ ಕೀಗಳು ಇಲ್ಲಿ ಗೋಚರಿಸುತ್ತವೆ.','Default delivery type' => 'ಡೀಫಾಲ್ಟ್ ವಿತರಣಾ ಪ್ರಕಾರ','Choose which delivery type will be selected by default.' => 'ಪೂರ್ವನಿಯೋಜಿತವಾಗಿ ಯಾವ ವಿತರಣಾ ಪ್ರಕಾರವನ್ನು ಆಯ್ಕೆ ಮಾಡಬೇಕೆಂದು ಆರಿಸಿ.','Shipping zone fields' => 'ಸಾಗಣೆ ವಲಯ ಕ್ಷೇತ್ರಗಳು','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ಸ್ಥಳೀಯ ಪಿಕಪ್ ಶಿಪ್ಪಿಂಗ್ ವಲಯ ಫಿಲ್ಟರ್ ಕ್ಷೇತ್ರಗಳಿಗೆ ಯಾವ ಕ್ಷೇತ್ರಗಳನ್ನು ಪ್ರದರ್ಶಿಸಬೇಕೆಂದು ಆರಿಸಿ. ಲಭ್ಯವಿರುವ ಎಲ್ಲಾ ಆಯ್ಕೆಗಳನ್ನು ತೋರಿಸಲು ಖಾಲಿ ಬಿಡಿ.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ಈ ಕ್ಷೇತ್ರಗಳನ್ನು ಸ್ಥಳೀಯ ಪಿಕಪ್ ಶಿಪ್ಪಿಂಗ್ ವಿಧಾನಗಳಿಗೆ ಫಿಲ್ಟರ್‌ನಂತೆ ಪ್ರದರ್ಶಿಸಲಾಗುತ್ತದೆ. ಹೊಂದಾಣಿಕೆಯ ಪ್ಲಗಿನ್‌ಗಳು ಸರಿಯಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸಲು ಅಗತ್ಯವಿದ್ದರೆ, ಇಲ್ಲಿ ಆಯ್ಕೆ ಮಾಡದಿದ್ದರೆ ಕೆಲವು ಕ್ಷೇತ್ರಗಳು ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ಇನ್ನೂ ಗೋಚರಿಸಬಹುದು.','Order shipping address' => 'ಆರ್ಡರ್ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸ','Order pay page optimization' => 'ಆರ್ಡರ್ ಪೇ ಪೇಜ್ ಆಪ್ಟಿಮೈಸೇಶನ್','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'ಪಾವತಿಸದ ಆರ್ಡರ್‌ಗಳಿಗೆ ಚೆಕ್‌ಔಟ್‌ನಂತೆಯೇ ಸ್ಪಷ್ಟ, ಪರಿವರ್ತನೆ-ಕೇಂದ್ರಿತ ವಿನ್ಯಾಸವನ್ನು ನೀಡಿ.','Optimize the layout of the order pay page for orders pending payment.' => 'ಬಾಕಿ ಇರುವ ಪಾವತಿಗಾಗಿ ಆರ್ಡರ್ ಪೇ ಪುಟದ ವಿನ್ಯಾಸವನ್ನು ಅತ್ಯುತ್ತಮಗೊಳಿಸಿ.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'ಸ್ಥಿರವಾದ ಖರೀದಿ ಪ್ರಯಾಣಕ್ಕಾಗಿ ಆರ್ಡರ್ ಪಾವತಿ ಅನುಭವವನ್ನು ನಿಮ್ಮ ಚೆಕ್‌ಔಟ್‌ಗೆ ಹೊಂದಿಸಿ.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'ಖರೀದಿದಾರರು ಪಾವತಿಸುವ ಮೊದಲು ಭರವಸೆ ಅಗತ್ಯವಿರುವ ಸ್ಥಳಗಳಲ್ಲಿ ನಂಬಿಕೆಯ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಿ.','Thank you page optimization' => 'ಧನ್ಯವಾದಗಳು ಪುಟ ಆಪ್ಟಿಮೈಸೇಶನ್','Make the thank you page and order details clearer for customers after they buy.' => 'ಗ್ರಾಹಕರು ಖರೀದಿಸಿದ ನಂತರ ಅವರಿಗೆ ಧನ್ಯವಾದ ಪುಟ ಮತ್ತು ಆರ್ಡರ್ ವಿವರಗಳನ್ನು ಸ್ಪಷ್ಟಪಡಿಸಿ.','Optimize the thank you page and account order details with a clearer layout.' => 'ಧನ್ಯವಾದ ಪುಟ ಮತ್ತು ಖಾತೆ ಆದೇಶದ ವಿವರಗಳನ್ನು ಸ್ಪಷ್ಟವಾದ ವಿನ್ಯಾಸದೊಂದಿಗೆ ಅತ್ಯುತ್ತಮಗೊಳಿಸಿ.','Show order status progress, actions, downloads, and notes where they make sense.' => 'ಆರ್ಡರ್ ಸ್ಥಿತಿ ಪ್ರಗತಿ, ಕ್ರಿಯೆಗಳು, ಡೌನ್‌ಲೋಡ್‌ಗಳು ಮತ್ತು ಟಿಪ್ಪಣಿಗಳನ್ನು ಅವು ಅರ್ಥಪೂರ್ಣವಾಗಿರುವಲ್ಲಿ ತೋರಿಸಿ.','Customize order details sections on email notifications.' => 'ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳಲ್ಲಿ ಆರ್ಡರ್ ವಿವರಗಳ ವಿಭಾಗಗಳನ್ನು ಕಸ್ಟಮೈಸ್ ಮಾಡಿ.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'ಖರೀದಿದಾರರಿಗೆ ಖರೀದಿಯ ನಂತರ ಧೈರ್ಯದ ಅಗತ್ಯವಿರುವ ಸ್ಥಳಗಳಲ್ಲಿ ನಂಬಿಕೆಯ ಚಿಹ್ನೆಗಳು ಮತ್ತು ಬ್ಯಾಡ್ಜ್‌ಗಳನ್ನು ಸೇರಿಸಿ.','Email notifications' => 'ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳು','Enable thank you page and order details optimizations to see more options' => 'ಹೆಚ್ಚಿನ ಆಯ್ಕೆಗಳನ್ನು ನೋಡಲು ಧನ್ಯವಾದ ಪುಟ ಮತ್ತು ಆರ್ಡರ್ ವಿವರಗಳ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Use wide layout on thank you page' => 'ಧನ್ಯವಾದ ಪುಟದಲ್ಲಿ ವಿಶಾಲ ವಿನ್ಯಾಸವನ್ನು ಬಳಸಿ.','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ಈ ಆಯ್ಕೆಗಳು ಧನ್ಯವಾದ ಪುಟದ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತವೆ, ಖಾತೆ ಪುಟಗಳಲ್ಲಿ ಮತ್ತು ಇಮೇಲ್ ಅಧಿಸೂಚನೆಗಳಲ್ಲಿ ಆರ್ಡರ್ ವಿವರಗಳನ್ನು ವೀಕ್ಷಿಸಿ.','Save settings' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಿ','Docs' => 'ಡಾಕ್ಸ್','Cart' => 'ಕಾರ್ಟ್','Thank you' => 'ಧನ್ಯವಾದಗಳು','Address autocomplete' => 'ವಿಳಾಸ ಸ್ವಯಂಪೂರ್ಣತೆ','Trust badges' => 'ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್‌ಗಳು','You do not have permission to save these settings.' => 'ಈ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಲು ನಿಮಗೆ ಅನುಮತಿ ಇಲ್ಲ.','Invalid save request.' => 'ಅಮಾನ್ಯವಾದ ಉಳಿಸು ವಿನಂತಿ.','Your settings have been saved.' => 'ನಿಮ್ಮ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಲಾಗಿದೆ.','Saving...' => 'ಉಳಿಸಲಾಗುತ್ತಿದೆ...','Settings could not be saved. Please try again.' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಉಳಿಸಲಾಗಲಿಲ್ಲ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Dismiss notice' => 'ಸೂಚನೆಯನ್ನು ವಜಾಗೊಳಿಸಿ','Open settings menu' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಮೆನು ತೆರೆಯಿರಿ','Close settings menu' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಮೆನು ಮುಚ್ಚಿ','Preview' => 'ಪೂರ್ವವೀಕ್ಷಣೆ','Expand preview' => 'ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ವಿಸ್ತರಿಸಿ','Collapse preview' => 'ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ಕುಗ್ಗಿಸಿ','Show header and footer' => 'ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿಯನ್ನು ತೋರಿಸಿ','Hide header and footer' => 'ಹೆಡರ್ ಮತ್ತು ಅಡಿಟಿಪ್ಪಣಿಯನ್ನು ಮರೆಮಾಡಿ','Page preview' => 'ಪುಟ ಪೂರ್ವವೀಕ್ಷಣೆ','Preview viewport' => 'ವ್ಯೂಪೋರ್ಟ್ ಪೂರ್ವವೀಕ್ಷಣೆ ಮಾಡಿ','Tablet' => 'ಟ್ಯಾಬ್ಲೆಟ್','Desktop' => 'ಡೆಸ್ಕ್‌ಟಾಪ್','Preview width' => 'ಪೂರ್ವವೀಕ್ಷಣೆ ಅಗಲ','Decrease width' => 'ಅಗಲ ಕಡಿಮೆ ಮಾಡಿ','Preview width in pixels' => 'ಪೂರ್ವವೀಕ್ಷಣೆ ಅಗಲ ಪಿಕ್ಸೆಲ್‌ಗಳಲ್ಲಿ','Increase width' => 'ಅಗಲ ಹೆಚ್ಚಿಸಿ','Preview as' => 'ಪೂರ್ವವೀಕ್ಷಣೆ ಮಾಡಿ','Guest' => 'ಅತಿಥಿ','Logged in' => 'ಲಾಗಿನ್ ಮಾಡಲಾಗಿದೆ','Preview page' => 'ಪುಟವನ್ನು ಪೂರ್ವವೀಕ್ಷಿಸಿ','Expand preview for a closer look' => 'ಹತ್ತಿರದ ನೋಟಕ್ಕಾಗಿ ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ವಿಸ್ತರಿಸಿ','Available with %s.' => '%s ಜೊತೆಗೆ ಲಭ್ಯವಿದೆ.','Turn them on' => 'ಅವುಗಳನ್ನು ಆನ್ ಮಾಡಿ','Optimizations for this page are turned off. %s to preview the page.' => 'ಈ ಪುಟದ ಆಪ್ಟಿಮೈಸೇಶನ್‌ಗಳನ್ನು ಆಫ್ ಮಾಡಲಾಗಿದೆ. ಪುಟವನ್ನು ಪೂರ್ವವೀಕ್ಷಿಸಲು %s.','%s preview' => '%s ಪೂರ್ವವೀಕ್ಷಣೆ','Isolated session · nothing is saved' => 'ಪ್ರತ್ಯೇಕ ಸೆಷನ್ · ಏನನ್ನೂ ಉಳಿಸಲಾಗಿಲ್ಲ','Usage tracking' => 'ಬಳಕೆಯ ಟ್ರ್ಯಾಕಿಂಗ್','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಹೊಂದಾಣಿಕೆಯನ್ನು ಸುಧಾರಿಸಲು ಸಹಾಯ ಮಾಡಲು ಸೂಕ್ಷ್ಮವಲ್ಲದ ಸೈಟ್ ಪರಿಸರ ವರದಿಗಳನ್ನು ಕಳುಹಿಸಿ. ಕೆಳಗಿನ ಆಯ್ಕೆಗಳಲ್ಲಿ ಸಕ್ರಿಯಗೊಳಿಸುವವರೆಗೆ ವರದಿಗಳನ್ನು ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.','Send usage tracking reports to Fluid Checkout' => 'ಬಳಕೆಯ ಟ್ರ್ಯಾಕಿಂಗ್ ವರದಿಗಳನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ಗೆ ಕಳುಹಿಸಿ','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'ಈ ವರದಿಗಳು ನಿಮ್ಮ ಸೈಟ್‌ಗೆ ಹೊಂದಾಣಿಕೆ ಮತ್ತು ಬೆಂಬಲವನ್ನು ಸುಧಾರಿಸಲು ನಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತವೆ ಮತ್ತು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ವಾರಕ್ಕೊಮ್ಮೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.','No customer, admin user, or any other sensitive data is included in the reports.' => 'ಯಾವುದೇ ಗ್ರಾಹಕರು, ನಿರ್ವಾಹಕ ಬಳಕೆದಾರರು ಅಥವಾ ಯಾವುದೇ ಇತರ ಸೂಕ್ಷ್ಮ ಡೇಟಾವನ್ನು ವರದಿಗಳಲ್ಲಿ ಸೇರಿಸಲಾಗಿಲ್ಲ.','Basic environment info' => 'ಮೂಲ ಪರಿಸರ ಮಾಹಿತಿ','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, ಥೀಮ್ ಮತ್ತು ಪ್ಲಗಿನ್ ಪಟ್ಟಿ ಡೇಟಾ. ವರದಿ ಮಾಡುವಿಕೆಯನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ ಯಾವಾಗಲೂ ಸೇರಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಸೈಟ್ ಚಾಲನೆಯಲ್ಲಿರುವ ಪರಿಸರವನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ನಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ.','Plugin settings' => 'ಪ್ಲಗಿನ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳು','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'ಬೆಂಬಲ ವಿನಂತಿಗಳಿಗೆ ಸಹಾಯ ಮಾಡಲು ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಪ್ಲಗಿನ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಕಳುಹಿಸುತ್ತದೆ ಮತ್ತು ನೀವು ನಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳನ್ನು ಹೇಗೆ ಬಳಸುತ್ತಿದ್ದೀರಿ ಎಂಬುದನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ನಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ.','Coming soon' => 'ಶೀಘ್ರದಲ್ಲೇ ಬರಲಿದೆ','Sales metrics' => 'ಮಾರಾಟ ಮಾಪನಗಳು','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಅನ್ನು ಸ್ಥಾಪಿಸುವ ಮೊದಲು ಇಂದಿನವರೆಗೆ ಒಂದು ವರ್ಷದ ಮಾಸಿಕ ಆರ್ಡರ್ ಎಣಿಕೆ ಮತ್ತು ಒಟ್ಟು ಮಾರಾಟಗಳು. ನಮ್ಮ ಪ್ಲಗಿನ್‌ಗಳನ್ನು ಸ್ಥಾಪಿಸುವುದರಿಂದ ನೀವು ಹೆಚ್ಚು ಹಣ ಗಳಿಸುತ್ತಿದ್ದೀರಾ ಎಂದು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ನಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಯಾವುದೇ ಗ್ರಾಹಕ ಅಥವಾ ಬಳಕೆದಾರ ಡೇಟಾವನ್ನು ಎಂದಿಗೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.','Utilities' => 'ಉಪಯುಕ್ತತೆಗಳು','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ಬದಲಿಗೆ <code>TomSelect</code> ಡ್ರಾಪ್‌ಡೌನ್ ಘಟಕಗಳನ್ನು ಬಳಸಿ','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect ಒಂದು ಸರಳವಾದ ಡ್ರಾಪ್‌ಡೌನ್ ಆಯ್ಕೆ ಘಟಕವಾಗಿದ್ದು, Select2 ಗಿಂತ ಇದು ದೋಷಗಳಿಗೆ ಕಡಿಮೆ ಒಳಗಾಗುತ್ತದೆ, ಆದರೆ ಅದೇ ಕಾರ್ಯವನ್ನು ನೀಡುತ್ತದೆ.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'ಸಣ್ಣ ಸಾಧನಗಳಲ್ಲಿ ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳೊಂದಿಗೆ ಸಂವಹನ ನಡೆಸುವಾಗ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಜೂಮ್ ಆಗುವುದನ್ನು ತಪ್ಪಿಸಲು ಈ ಪ್ಲಗಿನ್‌ನಿಂದ ಆಪ್ಟಿಮೈಸ್ ಮಾಡಲಾದ ಪುಟಗಳಲ್ಲಿ ಫಾರ್ಮ್ ಕ್ಷೇತ್ರಗಳೊಳಗಿನ ಫಾಂಟ್ ಗಾತ್ರವನ್ನು 16px ಗೆ ಹೊಂದಿಸುತ್ತದೆ.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ಫಾಂಟ್ ಗಾತ್ರವು 16px ಗಿಂತ ಚಿಕ್ಕದಾಗಿದ್ದಾಗ ಪಠ್ಯವನ್ನು ಸುಲಭವಾಗಿ ಓದಲು ಸಫಾರಿ ಮತ್ತು ಇತರ ಬ್ರೌಸರ್‌ಗಳು ಮೊಬೈಲ್ ಸಾಧನಗಳಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಜೂಮ್ ಇನ್ ಮಾಡಬಹುದು.','Enable script processing tracking on the browser console.' => 'ಬ್ರೌಸರ್ ಕನ್ಸೋಲ್‌ನಲ್ಲಿ ಸ್ಕ್ರಿಪ್ಟ್ ಪ್ರಕ್ರಿಯೆ ಟ್ರ್ಯಾಕಿಂಗ್ ಅನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','Unminified assets' => 'ಸಂಸ್ಕರಿಸದ ಸ್ವತ್ತುಗಳು','Google Maps scripts' => 'ಗೂಗಲ್ ನಕ್ಷೆಗಳ ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳು','Do not remove duplicate Google Maps scripts' => 'ನಕಲಿ Google Maps ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳನ್ನು ತೆಗೆದುಹಾಕಬೇಡಿ.','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ನಕಲಿ Google Maps ಸ್ಕ್ರಿಪ್ಟ್‌ಗಳನ್ನು ತೆಗೆದುಹಾಕಲಾಗುವುದಿಲ್ಲ, ಇದು ದೋಷಗಳು ಮತ್ತು ಕಾರ್ಯಕ್ಷಮತೆಯ ಸಮಸ್ಯೆಗಳನ್ನು ಉಂಟುಮಾಡಬಹುದು. ದೋಷನಿವಾರಣೆ ಮಾಡುವಾಗ ಮಾತ್ರ ಈ ಆಯ್ಕೆಯನ್ನು ಬಳಸಿ.','Widget areas' => 'ವಿಜೆಟ್ ಪ್ರದೇಶಗಳು','Last step on mobile' => 'ಮೊಬೈಲ್‌ನಲ್ಲಿ ಕೊನೆಯ ಹೆಜ್ಜೆ','Display widgets only at last step on mobile' => 'ಮೊಬೈಲ್‌ನಲ್ಲಿ ಕೊನೆಯ ಹಂತದಲ್ಲಿ ಮಾತ್ರ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'ಮೊಬೈಲ್ ಸಾಧನಗಳಲ್ಲಿ ಕೊನೆಯ ಚೆಕ್‌ಔಟ್ ಹಂತವನ್ನು ವೀಕ್ಷಿಸುವಾಗ ಮಾತ್ರ ಚೆಕ್‌ಔಟ್ ಟ್ರಸ್ಟ್ ಬ್ಯಾಡ್ಜ್ ವಿಜೆಟ್‌ಗಳನ್ನು ಪ್ರದರ್ಶಿಸಿ.','Standard' => 'ಪ್ರಮಾಣಿತ','VAT number field' => 'VAT ಸಂಖ್ಯೆ ಕ್ಷೇತ್ರ','Add a VAT number field to the billing form.' => 'ಬಿಲ್ಲಿಂಗ್ ಫಾರ್ಮ್‌ಗೆ VAT ಸಂಖ್ಯೆ ಕ್ಷೇತ್ರವನ್ನು ಸೇರಿಸಿ.','Field label' => 'ಫೀಲ್ಡ್ ಲೇಬಲ್','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT ಸಂಖ್ಯೆ ಕ್ಷೇತ್ರದ ಲೇಬಲ್ ಅನ್ನು ಹೊಂದಿಸಿ (ಅಂದರೆ VAT ಸಂಖ್ಯೆ). ಬಹು-ಭಾಷಾ ವೆಬ್‌ಸೈಟ್‌ಗಳಲ್ಲಿ, ಈ ಕ್ಷೇತ್ರವನ್ನು ಖಾಲಿ ಬಿಡುವುದು ಮತ್ತು ಮೂಲ ಸ್ಟ್ರಿಂಗ್ ಅನ್ನು ಅನುವಾದಿಸುವುದು ಉತ್ತಮ.','VAT Number' => 'ವ್ಯಾಟ್ ಸಂಖ್ಯೆ','EU-VAT' => 'EU-ವ್ಯಾಟ್','Enable the VAT number field to see more options' => 'ಹೆಚ್ಚಿನ ಆಯ್ಕೆಗಳನ್ನು ನೋಡಲು VAT ಸಂಖ್ಯೆ ಕ್ಷೇತ್ರವನ್ನು ಸಕ್ರಿಯಗೊಳಿಸಿ.','VAT validation' => 'ವ್ಯಾಟ್ ದೃಢೀಕರಣ','Validate VAT number field for EU-VAT during checkout' => 'ಚೆಕ್ಔಟ್ ಸಮಯದಲ್ಲಿ EU-VAT ಗಾಗಿ VAT ಸಂಖ್ಯೆ ಕ್ಷೇತ್ರವನ್ನು ಮೌಲ್ಯೀಕರಿಸಿ.','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'ಒದಗಿಸಲಾದ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯು ಯುರೋಪಿಯನ್ VIES ಡೇಟಾಬೇಸ್ (ವ್ಯಾಟ್ ಮಾಹಿತಿ ವಿನಿಮಯ ವ್ಯವಸ್ಥೆ) ನಲ್ಲಿ ನೋಂದಾಯಿಸಲಾದ ಮಾನ್ಯವಾದ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯೇ ಎಂದು ಪರಿಶೀಲಿಸುತ್ತದೆ.','Shop VAT number' => 'ಅಂಗಡಿಯ VAT ಸಂಖ್ಯೆ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'ಅಂಗಡಿಯ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯನ್ನು EU-VAT ದೃಢೀಕರಣವನ್ನು ವಿನಂತಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ಮುದ್ರಿಸಲಾಗುತ್ತದೆ.<br> <strong>ನಿಮ್ಮ ಅಂಗಡಿ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯನ್ನು ಸೇರಿಸಲು ನಾವು ಬಲವಾಗಿ ಶಿಫಾರಸು ಮಾಡುತ್ತೇವೆ</strong> , ಇಲ್ಲದಿದ್ದರೆ VIES ಸಮಾಲೋಚನೆಯ ಫಲಿತಾಂಶಗಳು ಲೆಕ್ಕಪತ್ರ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾನ್ಯವಾಗಿರುವುದಿಲ್ಲ.<br> ಅಂದರೆ: <code>ATU99999999</code> ಅಥವಾ <code>EE999999999</code> .','Reverse charge' => 'ರಿವರ್ಸ್ ಚಾರ್ಜ್','Apply reverse charge mechanism' => 'ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಕಾರ್ಯವಿಧಾನವನ್ನು ಅನ್ವಯಿಸಿ','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'ಗ್ರಾಹಕರ ವ್ಯಾಟ್ ಸಂಖ್ಯೆ ಮಾನ್ಯವಾಗಿದ್ದಾಗ, ತೆರಿಗೆ ದರವನ್ನು ಶೂನ್ಯಕ್ಕೆ ಹೊಂದಿಸಿ ಮತ್ತು ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ &quot;ರಿವರ್ಸ್ ಚಾರ್ಜ್&quot; ಅನ್ನು ಪ್ರದರ್ಶಿಸಿ. ಅಂಗಡಿಯ ದೇಶವನ್ನು ಅವಲಂಬಿಸಿ ವಿಭಿನ್ನ &quot;ರಿವರ್ಸ್ ಚಾರ್ಜ್&quot; ಪಠ್ಯದ ಅಗತ್ಯವಿರಬಹುದು.','Same country' => 'ಅದೇ ದೇಶ.','Apply reverse charge mechanism for transactions in the shop country:' => 'ಅಂಗಡಿ ದೇಶದಲ್ಲಿ ವಹಿವಾಟುಗಳಿಗೆ ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಕಾರ್ಯವಿಧಾನವನ್ನು ಅನ್ವಯಿಸಿ:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'ಅಂಗಡಿ ಇರುವ ದೇಶದಲ್ಲಿರುವ ಕಂಪನಿಗಳ ನಡುವಿನ ವಹಿವಾಟುಗಳಿಗೆ ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಕಾರ್ಯವಿಧಾನವನ್ನು ಅನ್ವಯಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.','Reverse charge exceptions' => 'ರಿವರ್ಸ್ ಚಾರ್ಜ್ ವಿನಾಯಿತಿಗಳು','Select additional countries to skip applying the reverse charge mechanism.' => 'ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಕಾರ್ಯವಿಧಾನವನ್ನು ಅನ್ವಯಿಸುವುದನ್ನು ಬಿಟ್ಟುಬಿಡಲು ಹೆಚ್ಚುವರಿ ದೇಶಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'ಈ ದೇಶಗಳ ಆರ್ಡರ್‌ಗಳಿಗೆ ಮಾನ್ಯವಾದ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯನ್ನು ಒದಗಿಸಿದ್ದರೂ ಸಹ ತೆರಿಗೆಗಳನ್ನು ವಿಧಿಸಲಾಗುತ್ತದೆ.','Reverse charge label on invoices' => 'ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಲೇಬಲ್','Set the label of "reverse charge" on the checkout page and order details.' => 'ಚೆಕ್ಔಟ್ ಪುಟದಲ್ಲಿ &quot;ರಿವರ್ಸ್ ಚಾರ್ಜ್&quot; ಲೇಬಲ್ ಅನ್ನು ಹೊಂದಿಸಿ ಮತ್ತು ಆರ್ಡರ್ ವಿವರಗಳನ್ನು ನೀಡಿ.','Reverse charge text on invoices' => 'ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಪಠ್ಯ','Set the label of "reverse charge" text on invoices.' => 'ಇನ್‌ವಾಯ್ಸ್‌ಗಳಲ್ಲಿ &quot;ರಿವರ್ಸ್ ಚಾರ್ಜ್&quot; ಪಠ್ಯದ ಲೇಬಲ್ ಅನ್ನು ಹೊಂದಿಸಿ.','Tax to be paid on reverse charge basis' => 'ರಿವರ್ಸ್ ಚಾರ್ಜ್ ಆಧಾರದ ಮೇಲೆ ತೆರಿಗೆಯನ್ನು ಪಾವತಿಸಬೇಕು.','Company name' => 'ಕಂಪನಿ ಹೆಸರು','Autocomplete company name from VAT number' => 'ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯಿಂದ ಕಂಪನಿಯ ಹೆಸರನ್ನು ಸ್ವಯಂಪೂರ್ಣಗೊಳಿಸಿ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ಗ್ರಾಹಕರು ಒದಗಿಸಿದ ಮಾನ್ಯವಾದ ವ್ಯಾಟ್ ಸಂಖ್ಯೆಯ ಆಧಾರದ ಮೇಲೆ ಬಿಲ್ಲಿಂಗ್ ಕಂಪನಿಯ ಹೆಸರನ್ನು ಭರ್ತಿ ಮಾಡಿ.','Company name editing' => 'ಕಂಪನಿ ಹೆಸರು ಸಂಪಾದನೆ','Allow editing of auto-filled company name' => 'ಸ್ವಯಂ ಭರ್ತಿ ಮಾಡಿದ ಕಂಪನಿಯ ಹೆಸರನ್ನು ಸಂಪಾದಿಸಲು ಅನುಮತಿಸಿ.','When enabled, customers can change the company name associated with the provided VAT number.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಗ್ರಾಹಕರು ಒದಗಿಸಲಾದ VAT ಸಂಖ್ಯೆಗೆ ಸಂಬಂಧಿಸಿದ ಕಂಪನಿಯ ಹೆಸರನ್ನು ಬದಲಾಯಿಸಬಹುದು.','EU-VAT for digital goods' => 'ಡಿಜಿಟಲ್ ಸರಕುಗಳಿಗೆ EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'ಜನವರಿ 1, 2015 ರಿಂದ, ಡಿಜಿಟಲ್ ಸರಕುಗಳಿಗೆ ಸಂಬಂಧಿಸಿದಂತೆ EU ವ್ಯಾಟ್ ನಿಯಮಗಳಿಗೆ ಮಾರ್ಪಾಡುಗಳನ್ನು ಮಾಡಲಾಗಿದೆ, ಇದು ಕೇವಲ B2C ವಹಿವಾಟುಗಳ ಮೇಲೆ ಪರಿಣಾಮ ಬೀರುತ್ತದೆ. ಡಿಜಿಟಲ್ ಸರಕುಗಳ ಮೇಲಿನ ವ್ಯಾಟ್ ಅನ್ನು ಗ್ರಾಹಕರ ಸ್ಥಳವನ್ನು ಆಧರಿಸಿ ಲೆಕ್ಕಹಾಕಬೇಕು ಮತ್ತು ಇದರ ಪುರಾವೆಗಳನ್ನು (IP ವಿಳಾಸ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸ) ಸಂಗ್ರಹಿಸಬೇಕಾಗುತ್ತದೆ.','Tax classes for digital goods' => 'ಡಿಜಿಟಲ್ ಸರಕುಗಳಿಗೆ ತೆರಿಗೆ ವರ್ಗಗಳು','Select some tax classes' => 'ಕೆಲವು ತೆರಿಗೆ ವರ್ಗಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ','Location evidence' => 'ಸ್ಥಳ ಪುರಾವೆಗಳು','Collect customer\'s location evidence' => 'ಗ್ರಾಹಕರ ಸ್ಥಳ ಪುರಾವೆಗಳನ್ನು ಸಂಗ್ರಹಿಸಿ','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP ವಿಳಾಸವನ್ನು ಉಳಿಸುತ್ತದೆ ಮತ್ತು ಗ್ರಾಹಕರ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಕ್ಕೆ ಅನುಗುಣವಾಗಿ ಅದನ್ನು ಮೌಲ್ಯೀಕರಿಸುತ್ತದೆ. ಗ್ರಾಹಕರು ತಮ್ಮ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸದಲ್ಲಿರುವ ದೇಶ ಮತ್ತು IP ಹೊಂದಿಕೆಯಾಗದಿದ್ದರೆ ಚೆಕ್‌ಔಟ್ ಪುಟದಲ್ಲಿ ಚೆಕ್‌ಬಾಕ್ಸ್ ಅನ್ನು ಪರಿಶೀಲಿಸುವ ಮೂಲಕ ತಮ್ಮ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸವನ್ನು ದೃಢೀಕರಿಸಬೇಕು.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ಈ ಆಯ್ಕೆಯನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗಿದೆ. <a href="%s">ಗ್ರಾಹಕ ಖಾತೆಗಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ ಇದನ್ನು ಬದಲಾಯಿಸಿ</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ಈ ಆಯ್ಕೆಯನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗಿದೆ. ಇದನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ &gt; ಗ್ರಾಹಕ ಖಾತೆಗಳು ಅಡಿಯಲ್ಲಿ ಬದಲಾಯಿಸಿ.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ಈ ಆಯ್ಕೆಯನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ. ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಸಕ್ರಿಯಗೊಂಡಾಗ ಶಿಪ್ಪಿಂಗ್ ಗಮ್ಯಸ್ಥಾನವನ್ನು ಯಾವಾಗಲೂ &quot;ಗ್ರಾಹಕ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸಕ್ಕೆ ಡೀಫಾಲ್ಟ್&quot; ಎಂದು ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಚೆಕ್‌ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರು ಇನ್ನೂ ವಿಭಿನ್ನ ಶಿಪ್ಪಿಂಗ್ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಗಳನ್ನು ಒದಗಿಸಬಹುದು.<br><br> ಡೀಫಾಲ್ಟ್ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸವನ್ನು ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ ಹೊಂದಿಸುವ ಆಯ್ಕೆಯು <a href="%s">ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಲ್ಲಿ</a> ಲಭ್ಯವಿದೆ.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ಈ ಆಯ್ಕೆಯನ್ನು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ನಿರ್ವಹಿಸಲಾಗುತ್ತದೆ. ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ ಸಕ್ರಿಯಗೊಂಡಾಗ ಶಿಪ್ಪಿಂಗ್ ಗಮ್ಯಸ್ಥಾನವನ್ನು ಯಾವಾಗಲೂ &quot;ಗ್ರಾಹಕ ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸಕ್ಕೆ ಡೀಫಾಲ್ಟ್&quot; ಎಂದು ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಚೆಕ್‌ಔಟ್ ಸಮಯದಲ್ಲಿ ಗ್ರಾಹಕರು ಇನ್ನೂ ವಿಭಿನ್ನ ಶಿಪ್ಪಿಂಗ್ ಮತ್ತು ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸಗಳನ್ನು ಒದಗಿಸಬಹುದು.<br><br> ಡೀಫಾಲ್ಟ್ ಬಿಲ್ಲಿಂಗ್ ವಿಳಾಸವನ್ನು ಶಿಪ್ಪಿಂಗ್ ವಿಳಾಸದಂತೆಯೇ ಹೊಂದಿಸಲು ಒಂದು ಆಯ್ಕೆ WooCommerce &gt; ಸೆಟ್ಟಿಂಗ್‌ಗಳು &gt; ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿ ಲಭ್ಯವಿದೆ.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ಈ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು WP ಅಡ್ಮಿನ್ &gt; ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ &gt; ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಸರಿಸಲಾಗಿದೆ.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ಈ WooCommerce ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಟ್ಯಾಬ್ ಅನ್ನು ಅಸಮ್ಮತಿಸಲಾಗಿದೆ ಮತ್ತು ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್ 6.0 ರಲ್ಲಿ ತೆಗೆದುಹಾಕಲಾಗುತ್ತದೆ.','Go to settings page' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಪುಟಕ್ಕೆ ಹೋಗಿ','Hide this tab permanently' => 'ಈ ಟ್ಯಾಬ್ ಅನ್ನು ಶಾಶ್ವತವಾಗಿ ಮರೆಮಾಡಿ','Site report preview' => 'ಸೈಟ್ ವರದಿ ಪೂರ್ವವೀಕ್ಷಣೆ','This is the data that would be included in the next site environment report based on your current settings.' => 'ನಿಮ್ಮ ಪ್ರಸ್ತುತ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಆಧಾರದ ಮೇಲೆ ಮುಂದಿನ ಸೈಟ್ ಪರಿಸರ ವರದಿಯಲ್ಲಿ ಸೇರಿಸಲಾಗುವ ಡೇಟಾ ಇದು.','Loading report preview...' => 'ವರದಿ ಪೂರ್ವವೀಕ್ಷಣೆ ಲೋಡ್ ಆಗುತ್ತಿದೆ...','Could not load the site report preview. Try again.' => 'ಸೈಟ್ ವರದಿ ಪೂರ್ವವೀಕ್ಷಣೆಯನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Could not send the site report. Try again.' => 'ಸೈಟ್ ವರದಿಯನ್ನು ಕಳುಹಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Site report sent successfully.' => 'ಸೈಟ್ ವರದಿಯನ್ನು ಯಶಸ್ವಿಯಾಗಿ ಕಳುಹಿಸಲಾಗಿದೆ.','Enable and send now' => 'ಸಕ್ರಿಯಗೊಳಿಸಿ ಮತ್ತು ಈಗ ಕಳುಹಿಸಿ','Close' => 'ಮುಚ್ಚಿ','A site report request is already in progress. Try again in a moment.' => 'ಸೈಟ್ ವರದಿ ವಿನಂತಿಯು ಈಗಾಗಲೇ ಪ್ರಗತಿಯಲ್ಲಿದೆ. ಸ್ವಲ್ಪ ಸಮಯದ ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Site environment reporting is disabled.' => 'ಸೈಟ್ ಪರಿಸರ ವರದಿ ಮಾಡುವಿಕೆಯನ್ನು ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಲಾಗಿದೆ.','No site report data is available to send.' => 'ಕಳುಹಿಸಲು ಯಾವುದೇ ಸೈಟ್ ವರದಿ ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ.','This site domain cannot send environment reports (local or development domains are excluded).' => 'ಈ ಸೈಟ್ ಡೊಮೇನ್ ಪರಿಸರ ವರದಿಗಳನ್ನು ಕಳುಹಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ (ಸ್ಥಳೀಯ ಅಥವಾ ಅಭಿವೃದ್ಧಿ ಡೊಮೇನ್‌ಗಳನ್ನು ಹೊರತುಪಡಿಸಲಾಗಿದೆ).','A site report was sent recently. Try again later.' => 'ಇತ್ತೀಚೆಗೆ ಸೈಟ್ ವರದಿಯನ್ನು ಕಳುಹಿಸಲಾಗಿದೆ. ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','The site report could not be sent. Try again later.' => 'ಸೈಟ್ ವರದಿಯನ್ನು ಕಳುಹಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.','Site environment reporting is not available.' => 'ಸೈಟ್ ಪರಿಸರ ವರದಿ ಮಾಡುವಿಕೆ ಲಭ್ಯವಿಲ್ಲ.','No site report data is available for the selected settings.' => 'ಆಯ್ಕೆಮಾಡಿದ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಯಾವುದೇ ಸೈಟ್ ವರದಿ ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ.','You are not allowed to manage site reports.' => 'ಸೈಟ್ ವರದಿಗಳನ್ನು ನಿರ್ವಹಿಸಲು ನಿಮಗೆ ಅನುಮತಿ ಇಲ್ಲ.','PRO feature' => 'PRO ವೈಶಿಷ್ಟ್ಯ','Other plugins' => 'ಇತರ ಪ್ಲಗಿನ್‌ಗಳು','Get only this add-on &mdash; %s' => 'ಈ ಆಡ್-ಆನ್ ಅನ್ನು ಮಾತ್ರ ಪಡೆಯಿರಿ — %s','Install add-on' => 'ಆಡ್-ಆನ್ ಸ್ಥಾಪಿಸಿ','Upgrade to PRO &mdash; %s' => 'PRO ಗೆ ಅಪ್‌ಗ್ರೇಡ್ ಮಾಡಿ — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'ಈ ಆಯ್ಕೆಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಲು <a target="_blank" href="%1$s">%2$s ಪಡೆಯಿರಿ</a> .','Add-on' => 'ಆಡ್-ಆನ್','View documentation' => 'ದಸ್ತಾವೇಜನ್ನು ವೀಕ್ಷಿಸಿ','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'ವಿನಂತಿಗಳಿಗೆ ಲಾಗಿನ್ ಆಗಿರುವ WordPress ಬಳಕೆದಾರನ ಅಗತ್ಯವಿದೆ. ಪ್ರಸ್ತುತ ಬಳಕೆದಾರರ ಡೇಟಾವನ್ನು ಬಳಸಲು user_id ಅನ್ನು ಬಿಟ್ಟುಬಿಡಿ, ಅಥವಾ ಕರೆ ಮಾಡುವವರು ಆ ಬಳಕೆದಾರರನ್ನು ಸಂಪಾದಿಸಬಹುದಾದಾಗ (edit_user ಸಾಮರ್ಥ್ಯ) ಮತ್ತೊಂದು ಖಾತೆಯನ್ನು ಗುರಿಯಾಗಿಸಲು user_id ಅನ್ನು ಪಾಸ್ ಮಾಡಿ. ದೃಢೀಕರಿಸದ ವಿನಂತಿಗಳು fc_api_forbidden ಅನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತವೆ. ಅಮಾನ್ಯವಾದ user_id fc_api_user_not_found ಅನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತದೆ.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'ಹ್ಯಾಂಡ್ಲರ್ ಪೇಲೋಡ್ ಅನ್ನು ಹಿಂತಿರುಗಿಸಿದಾಗ { &quot;data&quot;: { ... } } ನೊಂದಿಗೆ HTTP 200.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'ಪೇಲೋಡ್ ಇಲ್ಲದಿದ್ದಾಗ (ಉದಾಹರಣೆಗೆ DELETE) { &quot;success&quot;: true } ನೊಂದಿಗೆ HTTP 200.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ವೈಫಲ್ಯಗಳು WP_Error ನಿಂದ WordPress REST ದೋಷ JSON ಅನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತವೆ (ಕೋಡ್, ಸಂದೇಶ, ಡೇಟಾ.ಸ್ಟೇಟಸ್). ವೈರ್ ಕೋಡ್‌ಗಳು fc_api_* ಪೂರ್ವಪ್ರತ್ಯಯವನ್ನು ಬಳಸುತ್ತವೆ.','Forbidden access.' => 'ಪ್ರವೇಶ ನಿಷೇಧಿಸಲಾಗಿದೆ.','Target user was not found.' => 'ಗುರಿ ಬಳಕೆದಾರರು ಕಂಡುಬಂದಿಲ್ಲ.','This feature is not available.' => 'ಈ ವೈಶಿಷ್ಟ್ಯವು ಲಭ್ಯವಿಲ್ಲ.','A required address field is missing.' => 'ಅಗತ್ಯವಿರುವ ವಿಳಾಸ ಕ್ಷೇತ್ರ ಕಾಣೆಯಾಗಿದೆ.','Postcode or ZIP is invalid.' => 'ಪೋಸ್ಟ್‌ಕೋಡ್ ಅಥವಾ ಪಿನ್ ಅಮಾನ್ಯವಾಗಿದೆ.','Phone number is invalid.' => 'ಫೋನ್ ಸಂಖ್ಯೆ ಅಮಾನ್ಯವಾಗಿದೆ.','State or county is invalid.' => 'ರಾಜ್ಯ ಅಥವಾ ಕೌಂಟಿ ಅಮಾನ್ಯವಾಗಿದೆ.','Country is invalid or has no address fields.' => 'ದೇಶವು ಅಮಾನ್ಯವಾಗಿದೆ ಅಥವಾ ಯಾವುದೇ ವಿಳಾಸ ಕ್ಷೇತ್ರಗಳನ್ನು ಹೊಂದಿಲ್ಲ.','The request could not be processed.' => 'ವಿನಂತಿಯನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ.','Back to previous step' => 'ಹಿಂದಿನ ಹಂತಕ್ಕೆ ಹಿಂತಿರುಗಿ','Skip to settings' => 'ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಹೋಗಿ','Start over and return to the first guided setup step' => 'ಮತ್ತೆ ಪ್ರಾರಂಭಿಸಿ ಮತ್ತು ಮೊದಲ ಮಾರ್ಗದರ್ಶಿ ಸೆಟಪ್ ಹಂತಕ್ಕೆ ಹಿಂತಿರುಗಿ','Start over' => 'ಮತ್ತೆ ಪ್ರಾರಂಭಿಸಿ','Please complete all sub-steps before continuing.' => 'ಮುಂದುವರಿಯುವ ಮೊದಲು ದಯವಿಟ್ಟು ಎಲ್ಲಾ ಉಪ-ಹಂತಗಳನ್ನು ಪೂರ್ಣಗೊಳಿಸಿ.','Expand' => 'ವಿಸ್ತರಿಸಿ','Collapse' => 'ಕುಗ್ಗಿಸು','Skip' => 'ಬಿಟ್ಟುಬಿಡಿ','Mark as complete' => 'ಪೂರ್ಣಗೊಂಡಿದೆ ಎಂದು ಗುರುತಿಸಿ','Mark as incomplete' => 'ಅಪೂರ್ಣ ಎಂದು ಗುರುತಿಸಿ','View full-size image: %s' => 'ಪೂರ್ಣ ಗಾತ್ರದ ಚಿತ್ರವನ್ನು ವೀಕ್ಷಿಸಿ: %s','Full-size setup guide image' => 'ಪೂರ್ಣ-ಗಾತ್ರದ ಸೆಟಪ್ ಮಾರ್ಗದರ್ಶಿ ಚಿತ್ರ','Close image' => 'ಚಿತ್ರವನ್ನು ಮುಚ್ಚಿ','Fluid Checkout Guided Setup' => 'ದ್ರವ ಚೆಕ್ಔಟ್ ಮಾರ್ಗದರ್ಶಿ ಸೆಟಪ್','Welcome' => 'ಸ್ವಾಗತ','Explore your checkout' => 'ನಿಮ್ಮ ಚೆಕ್ಔಟ್ ಅನ್ನು ಅನ್ವೇಷಿಸಿ','All set' => 'ಎಲ್ಲವೂ ಸಿದ್ಧವಾಗಿದೆ','You do not have permission to access this page.' => 'ಈ ಪುಟವನ್ನು ಪ್ರವೇಶಿಸಲು ನಿಮಗೆ ಅನುಮತಿ ಇಲ್ಲ.','Go to step %1$d: %2$s' => 'ಹಂತ %1$d ಕ್ಕೆ ಹೋಗಿ: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'ಈ ಮಾರ್ಗದರ್ಶಿ ಸೆಟಪ್ ನಿಮಗೆ ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನೊಂದಿಗೆ ಪರಿಚಿತರಾಗಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಕೆಳಗಿನ ಹಂತಗಳು ಇದೀಗ ಪ್ಲೇಸ್‌ಹೋಲ್ಡರ್‌ಗಳಾಗಿವೆ.','Continue to the next step when you are ready.' => 'ನೀವು ಸಿದ್ಧರಾದಾಗ ಮುಂದಿನ ಹಂತಕ್ಕೆ ಮುಂದುವರಿಯಿರಿ.','Open your store checkout to see Fluid Checkout in action.' => 'ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಕಾರ್ಯರೂಪದಲ್ಲಿರುವುದನ್ನು ನೋಡಲು ನಿಮ್ಮ ಅಂಗಡಿ ಚೆಕ್ಔಟ್ ತೆರೆಯಿರಿ.','View checkout page' => 'ಚೆಕ್ಔಟ್ ಪುಟವನ್ನು ವೀಕ್ಷಿಸಿ','You can return to Fluid Checkout settings to continue configuring your store.' => 'ನಿಮ್ಮ ಅಂಗಡಿಯನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡುವುದನ್ನು ಮುಂದುವರಿಸಲು ನೀವು ಫ್ಲೂಯಿಡ್ ಚೆಕ್ಔಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಹಿಂತಿರುಗಬಹುದು.','Review checkout and cart settings' => 'ಚೆಕ್ಔಟ್ ಮತ್ತು ಕಾರ್ಟ್ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಪರಿಶೀಲಿಸಿ','Explore add-ons from the dashboard' => 'ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಆಡ್-ಆನ್‌ಗಳನ್ನು ಅನ್ವೇಷಿಸಿ','Finish & go to settings' => 'ಮುಗಿಸಿ ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಗೆ ಹೋಗಿ','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ಸಂಪ್ರದಾಯಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗುವಂತೆ ಲೆಗಸಿ ಮೌಲ್ಯದಿಂದ ಬಿಲ್ಲಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರ ಗೋಚರತೆ ಆಯ್ಕೆಯನ್ನು ನವೀಕರಿಸಿ.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ಸಂಪ್ರದಾಯಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗುವಂತೆ ಲೆಗಸಿ ಮೌಲ್ಯದಿಂದ ಶಿಪ್ಪಿಂಗ್ ಫೋನ್ ಕ್ಷೇತ್ರ ಗೋಚರತೆಯ ಆಯ್ಕೆಯನ್ನು ನವೀಕರಿಸಿ.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ಆರ್ಡರ್ ಸಾರಾಂಶ ಹಿನ್ನೆಲೆ ಬಣ್ಣದ ಸೆಟ್ಟಿಂಗ್ ಅನ್ನು ಹೊಸ ಸ್ಪ್ಲಿಟ್ ವಿನ್ಯಾಸ ದ್ವಿತೀಯ ಕಾಲಮ್ ಹಿನ್ನೆಲೆ ಬಣ್ಣದ ಆಯ್ಕೆಗೆ ನಕಲಿಸಿ.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'ಬೈಟ್‌ಶಿಪ್ ಪ್ಲಗಿನ್ ಬಳಸುವಾಗ ವರ್ಧಿತ ಆಯ್ಕೆ ಕ್ಷೇತ್ರಗಳ ವೈಶಿಷ್ಟ್ಯವು ಯಾವಾಗಲೂ ನಿಷ್ಕ್ರಿಯವಾಗಿರುತ್ತದೆ.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ಜರ್ಮನ್ ಮಾರುಕಟ್ಟೆಯನ್ನು ಬಳಸುವಾಗ ಸ್ಥಳ ಕ್ರಮದ ಸ್ಥಾನವನ್ನು ಯಾವಾಗಲೂ &quot;ಆದೇಶ ಸಾರಾಂಶದ ಕೆಳಗೆ&quot; ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಆ ಪ್ಲಗಿನ್‌ಗೆ ಸ್ಥಳ ಕ್ರಮ ಬಟನ್ ಮತ್ತು ಕಾನೂನು ಚೆಕ್‌ಬಾಕ್ಸ್‌ಗಳನ್ನು ಆದೇಶ ಸಾರಾಂಶದ ಕೆಳಗೆ ಪ್ರದರ್ಶಿಸುವ ಅಗತ್ಯವಿದೆ.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce ಗಾಗಿ ಜರ್ಮನೀಕರಿಸಿದ ಸ್ಥಾನ ಬಳಸುವಾಗ ಸ್ಥಳ ಕ್ರಮದ ಸ್ಥಾನವನ್ನು ಯಾವಾಗಲೂ &quot;ಆದೇಶ ಸಾರಾಂಶದ ಕೆಳಗೆ&quot; ಹೊಂದಿಸಲಾಗುತ್ತದೆ. ಆ ಪ್ಲಗಿನ್‌ಗೆ ಸ್ಥಳ ಕ್ರಮ ಬಟನ್ ಮತ್ತು ಕಾನೂನು ಚೆಕ್‌ಬಾಕ್ಸ್‌ಗಳನ್ನು ಆದೇಶ ಸಾರಾಂಶದ ಕೆಳಗೆ ಪ್ರದರ್ಶಿಸುವ ಅಗತ್ಯವಿದೆ.','Edit pickup locations' => 'ಪಿಕಪ್ ಸ್ಥಳಗಳನ್ನು ಸಂಪಾದಿಸಿ','Use local pickup label from WooCommerce settings' => 'WooCommerce ಸೆಟ್ಟಿಂಗ್‌ಗಳಿಂದ ಸ್ಥಳೀಯ ಪಿಕಪ್ ಲೇಬಲ್ ಬಳಸಿ','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'ಸಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಚೆಕ್‌ಔಟ್‌ನಲ್ಲಿರುವ ಪಿಕಪ್ ಆಯ್ಕೆಯ ಲೇಬಲ್ WooCommerce ಪಿಕಪ್ ಸ್ಥಳ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಶೀರ್ಷಿಕೆಗೆ ಹೊಂದಿಕೆಯಾಗುತ್ತದೆ. ನಿಷ್ಕ್ರಿಯಗೊಳಿಸಿದಾಗ, ಲೇಬಲ್ ಫ್ಲೂಯಿಡ್ ಚೆಕ್‌ಔಟ್‌ನಿಂದ ಅನುವಾದಿಸಬಹುದಾದ &quot;ಸ್ಥಳೀಯ ಪಿಕಪ್&quot; ಪ